(window.DishcoverDetail=window.DishcoverDetail||{q:[]}).q.push(["japan-korea",{"sushi":{"pron":"SOO-shee","what":"Bite-sized Japanese pieces of slightly sweet vinegar rice with fish, seafood or vegetables, often rolled in seaweed. Not all sushi is raw fish!","ingredients":["Sushi rice (with vinegar)","Raw/cooked fish or veggies","Nori seaweed","Soy sauce, wasabi, pickled ginger"],"texture":["Soft rice","Silky fish","Crisp seaweed"],"goodFor":["Light meals","Seafood","Trying something new"],"tip":"Nervous? Order a cooked or veg roll like a California or cucumber roll first.","steps":[{"icon":"🥢","text":"Use chopsticks — or your fingers. Eating sushi by hand is completely normal."},{"icon":"🫗","text":"Pour a little soy sauce in the small dish. Dip lightly — fish side down, not the rice (it falls apart)."},{"icon":"🟢","text":"Wasabi is very hot, like strong mustard. Use a tiny dab or skip it."},{"icon":"👄","text":"Eat each piece in one bite if you can."},{"icon":"🫚","text":"The pink pickled ginger is a palate cleanser — eat a slice between different pieces."}],"reviews":{"rating":4.4,"summary":"Fresh and light; many beginners start with veg or cooked rolls and love them. Raw fish isn't for everyone.","loved":["Fresh & light","Veg & cooked options"],"watch":["Raw fish","Wasabi surprise"],"samples":[{"name":"Tanvi","stars":5,"text":"Started with avocado and cucumber rolls. Now I'm hooked."},{"name":"Ravi","stars":3,"text":"Too much wasabi went straight to my nose 😭 Use a tiny bit!"},{"name":"Ken","stars":5,"text":"Dip fish side down. Game changer."}]},"photo":{"src":"images/sushi.jpg","title":"Sushi platter.jpg","author":"chidorian from Japan","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"https://commons.wikimedia.org/wiki/File:Sushi_platter.jpg","thumb":"images/thumb/sushi.jpg"}},"ramen":{"pron":"RAH-men","what":"A big bowl of Japanese wheat noodles in a rich, hot broth, topped with things like egg, meat slices, greens and seaweed. Nothing like instant noodles!","ingredients":["Wheat noodles","Broth (pork, chicken, miso or veg)","Soft-boiled egg","Meat or tofu","Spring onions"],"texture":["Slurpy noodles","Rich broth"],"goodFor":["Noodles","Soups","Hearty meals"],"tip":"Rest noodles on your spoon — no splashes on your shirt!","steps":[{"icon":"🥄","text":"Taste the broth first with the spoon — it's the heart of the dish."},{"icon":"🥢","text":"Lift noodles with chopsticks, rest them on the spoon, and eat. Slurping is fine (even polite in Japan)."},{"icon":"⏱️","text":"Eat fairly quickly — noodles go soft if they sit too long."},{"icon":"🥚","text":"Bite into the egg — the yolk is often soft and jammy."},{"icon":"🍲","text":"Finish with the broth using the spoon, or sip from the bowl."}],"reviews":{"rating":4.6,"summary":"Warm, filling and comforting. Very satisfying; some bowls are salty or heavy.","loved":["Deep, rich flavour","Very filling"],"watch":["Salty broth","Pork-based broths are common"],"samples":[{"name":"Aditi","stars":5,"text":"Miso ramen on a rainy day. Perfect."},{"name":"Sid","stars":4,"text":"Ask which broth is veg — many are pork or chicken."},{"name":"Hana","stars":5,"text":"Slurp! Nobody judges, I promise."}]},"photo":{"src":"images/ramen.jpg","title":"Shoyu Ramen（Tokyo Ramen） - 01.jpg","author":"Quercus acuta","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"https://commons.wikimedia.org/wiki/File:Shoyu_Ramen%EF%BC%88Tokyo_Ramen%EF%BC%89_-_01.jpg","thumb":"images/thumb/ramen.jpg"}},"bibimbap":{"pron":"BEE-bim-bahp","what":"A Korean rice bowl topped with neat sections of vegetables, meat or tofu and a fried egg. 'Bibim' means mixed — you mix it before eating.","ingredients":["Rice","Seasoned veggies","Beef / tofu","Fried egg","Gochujang (sweet-spicy chilli paste)"],"texture":["Crunchy veggies","Soft rice","Crispy bottom (stone bowl)"],"goodFor":["Rice bowls","Veggies","Mild-to-medium spice"],"tip":"Mix, mix, mix! An unmixed bibimbap is a sad bibimbap.","steps":[{"icon":"🌶️","text":"Add gochujang chilli paste — start with a little, it's spicy-sweet."},{"icon":"🥄","text":"Mix everything together thoroughly with your spoon, breaking the egg yolk."},{"icon":"🔥","text":"In a hot stone bowl (dolsot)? Don't touch it! Let the rice crisp at the bottom for a minute."},{"icon":"😋","text":"Eat with the spoon (Koreans use spoons for rice). Scrape up the crispy bits."}],"reviews":{"rating":4.6,"summary":"Colourful, healthy-feeling and filling. People love the crispy rice in stone bowls; spice level varies.","loved":["Healthy & filling","Crispy rice"],"watch":["Stone bowl is very hot","Chilli paste is spicy"],"samples":[{"name":"Divya","stars":5,"text":"Mix it all! That's the fun part."},{"name":"Varun","stars":4,"text":"Tastes like a Korean biryani-salad combo. Weird but great."},{"name":"Jin","stars":5,"text":"Wait for the crispy rice at the bottom 👌"}]},"photo":{"src":"images/bibimbap.jpg","title":"Dolsot-bibimbap.jpg","author":"Sous Chef","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"https://commons.wikimedia.org/wiki/File:Dolsot-bibimbap.jpg","thumb":"images/thumb/bibimbap.jpg"}},"tempura":{"pron":"tem-POO-rah","what":"Seafood and vegetables dipped in a very light batter and deep-fried until crisp and lacy. Lighter than Indian pakoras.","ingredients":["Prawns / fish or vegetables","Light flour-egg batter","Tentsuyu dipping sauce","Grated daikon"],"texture":["Light & crispy","Tender inside"],"goodFor":["Pakora","Fried prawns","Light fried food"],"tip":"Vegetable tempura is a great veg-ish pick, but the batter usually has egg.","steps":[{"icon":"🥢","text":"Pick up a piece with chopsticks."},{"icon":"🫗","text":"Mix the grated radish into the dipping sauce, then dip briefly."},{"icon":"🧂","text":"Or sprinkle a little salt and squeeze lemon."},{"icon":"⏱️","text":"Eat right away while crispy."}],"reviews":{"rating":4.5,"summary":"Light and crispy — easy to love. Gets soggy if it sits.","loved":["Light & crispy","Veg options"],"watch":["Batter has egg","Soggy if left"],"samples":[{"name":"Kenji","stars":5,"text":"Prawn tempura, freshly fried. Perfect."},{"name":"Deepak","stars":4,"text":"Like a super-light pakora!"},{"name":"Anna","stars":4,"text":"Veggie tempura is great too."}]},"photo":{"src":"images/tempura.jpg","title":"Tempura 01.jpg","author":"Yaco*","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"https://commons.wikimedia.org/wiki/File:Tempura_01.jpg","thumb":"images/thumb/tempura.jpg"}},"udon":{"pron":"OO-don","what":"Thick, chewy, white wheat noodles in a light, savoury broth, topped with spring onions, tempura or tofu. Milder than ramen.","ingredients":["Thick wheat noodles","Dashi broth (often fish-based)","Soy sauce & mirin","Spring onion, tempura or fried tofu"],"texture":["Thick & chewy noodles","Light broth"],"goodFor":["Noodle soups","Ramen","Mild food"],"tip":"Ramen = rich broth, thin noodles. Udon = light broth, thick noodles.","steps":[{"icon":"🥢","text":"Lift noodles with chopsticks; slurping is normal."},{"icon":"🥄","text":"Sip the broth from the spoon or bowl."},{"icon":"🌶️","text":"Sprinkle shichimi (chilli powder) for a little heat."},{"icon":"❓","text":"Veg? Ask for kombu (seaweed) broth — standard dashi uses fish."}],"reviews":{"rating":4.5,"summary":"Comforting and mild with fun chewy noodles. Broth usually contains fish.","loved":["Chewy noodles","Mild comforting broth"],"watch":["Fish-based broth","Plain for spice lovers"],"samples":[{"name":"Yuki","stars":5,"text":"Kitsune udon with sweet fried tofu — so comforting."},{"name":"Raj","stars":4,"text":"Fatter, chewier than ramen noodles. Loved it."},{"name":"Lisa","stars":4,"text":"Add shichimi for a kick."}]},"photo":{"src":"images/udon.jpg","title":"Kakeudon.jpg","author":"Lusheeta at Japanese Wikipedia","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/","source":"https://commons.wikimedia.org/wiki/File:Kakeudon.jpg","thumb":"images/thumb/udon.jpg"}},"gyoza":{"pron":"GYOH-zah","what":"Japanese dumplings, pan-fried crispy on one side and steamed soft on top. Usually filled with pork and cabbage; veg versions exist.","ingredients":["Thin wheat wrappers","Pork & cabbage or veg filling","Garlic & ginger","Soy-vinegar-chilli oil dip"],"texture":["Crispy bottom","Soft top","Juicy"],"goodFor":["Momos","Dumplings","Crispy snacks"],"tip":"Love momos? Gyoza are the Japanese pan-fried cousin.","steps":[{"icon":"🫗","text":"Make your dip: soy sauce + a little vinegar + a few drops of chilli oil."},{"icon":"🥢","text":"Pick one up with chopsticks, crispy side down."},{"icon":"🔥","text":"Dip and bite in half — the filling is hot and juicy."}],"reviews":{"rating":4.6,"summary":"Crispy-juicy and easy to love, especially if you like momos.","loved":["Crispy bottom","Juicy filling"],"watch":["Hot juices","Usually pork"],"samples":[{"name":"Haruto","stars":5,"text":"That crispy bottom is the best."},{"name":"Pooja","stars":4,"text":"Like pan-fried momos. Loved the veg ones."},{"name":"Mike","stars":4,"text":"Vinegar in the dip is a game changer."}]},"photo":{"src":"images/gyoza.jpg","title":"Japanese food by Naoki Nakashima 202.jpg","author":"nakashi","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"https://commons.wikimedia.org/wiki/File:Japanese_food_by_Naoki_Nakashima_202.jpg","thumb":"images/thumb/gyoza.jpg"}},"onigiri":{"pron":"oh-nee-GEE-ree","what":"A Japanese rice ball, often triangle-shaped and wrapped in seaweed, with a filling like tuna-mayo, salmon or pickled plum. A handy snack.","ingredients":["Japanese rice","Nori seaweed","Filling: tuna mayo / salmon / pickled plum / kombu"],"texture":["Soft sticky rice","Crisp seaweed"],"goodFor":["Rice","Sushi","Light snacks"],"tip":"Veg? Look for kombu (seaweed), plum (umeboshi) or plain salted rice balls.","steps":[{"icon":"🔢","text":"Packaged onigiri: pull tab 1 down the middle, then pull corners 2 and 3 — the seaweed stays crisp."},{"icon":"🤲","text":"Eat with your hands."},{"icon":"😋","text":"Bite from the top corner to reach the filling."}],"reviews":{"rating":4.4,"summary":"Simple and filling. Plain if you expect lots of flavour.","loved":["Easy snack","Many fillings"],"watch":["Plain taste","Fillings often fish"],"samples":[{"name":"Aiko","stars":5,"text":"Salmon onigiri — perfect train snack."},{"name":"Nikhil","stars":3,"text":"The packaging puzzle took me a minute."},{"name":"Sara","stars":4,"text":"Tuna mayo is the crowd favourite."}]},"photo":{"src":"images/onigiri.jpg","title":"小料理バルさくら 特製おにぎり.jpg","author":"脇山航","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"https://commons.wikimedia.org/wiki/File:%E5%B0%8F%E6%96%99%E7%90%86%E3%83%90%E3%83%AB%E3%81%95%E3%81%8F%E3%82%89_%E7%89%B9%E8%A3%BD%E3%81%8A%E3%81%AB%E3%81%8E%E3%82%8A.jpg","thumb":"images/thumb/onigiri.jpg"}},"takoyaki":{"pron":"tah-koh-YAH-kee","what":"Round, crispy-soft batter balls with a piece of octopus inside, topped with sweet sauce, mayo, seaweed flakes and dancing bonito flakes.","ingredients":["Wheat batter","Octopus","Takoyaki sauce & mayo","Bonito flakes & aonori"],"texture":["Crispy outside","Gooey inside","Chewy octopus"],"goodFor":["Seafood","Street food","Savoury snacks"],"tip":"Wait 30 seconds after opening one — the inside is lava.","steps":[{"icon":"🔥","text":"They're VERY hot inside — poke one open first."},{"icon":"🍡","text":"Use the toothpick or chopsticks to pick one up."},{"icon":"🌀","text":"The bonito flakes \"dance\" from the heat — they're not alive!"}],"reviews":{"rating":4.5,"summary":"Fun, gooey Osaka street food. Burnt tongues are common; octopus chewiness isn't for all.","loved":["Gooey & savoury","Fun toppings"],"watch":["Lava hot","Contains octopus"],"samples":[{"name":"Kaito","stars":5,"text":"Osaka street takoyaki. Burnt my tongue, no regrets."},{"name":"Riya","stars":3,"text":"Chewy octopus surprised me."},{"name":"Ben","stars":4,"text":"Poke it open and wait 30 seconds!"}]},"photo":{"src":"images/takoyaki.jpg","title":"Takoyaki.jpg","author":"Keith Pomakis","license":"CC BY-SA 2.5","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.5","source":"https://commons.wikimedia.org/wiki/File:Takoyaki.jpg","thumb":"images/thumb/takoyaki.jpg"}},"mochi":{"pron":"MOH-chee","what":"Soft, stretchy, chewy rice cakes. The cafe kind (daifuku) is a mochi ball filled with sweet red bean paste, ice cream or fruit.","ingredients":["Glutinous rice (mochiko)","Sweet red bean paste / ice cream / strawberry","Potato starch dusting"],"texture":["Very chewy","Stretchy","Soft"],"goodFor":["Chewy sweets","Red bean","Bubble tea pearls"],"tip":"Small bites and chew well — mochi is very sticky.","steps":[{"icon":"🤏","text":"Pick it up with fingers (dusted powder may get on you)."},{"icon":"😋","text":"Take small bites and chew well — it's very sticky."},{"icon":"🍦","text":"Mochi ice cream: let it soften 2 minutes first."}],"reviews":{"rating":4.4,"summary":"The chewy texture is the star — some love it, some find it odd.","loved":["Fun chewy texture","Not too sweet"],"watch":["Very sticky","Texture is unusual"],"samples":[{"name":"Hana","stars":5,"text":"Strawberry daifuku is heaven."},{"name":"Arjun","stars":3,"text":"Super chewy. Took getting used to."},{"name":"Lily","stars":4,"text":"Mochi ice cream is a great first try."}]},"photo":{"src":"images/mochi.jpg","title":"Two pieces of daifuku mochi on a decorative plate.jpg","author":"2benny","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"https://commons.wikimedia.org/wiki/File:Two_pieces_of_daifuku_mochi_on_a_decorative_plate.jpg","thumb":"images/thumb/mochi.jpg"}},"tteokbokki":{"pron":"TUH-bok-ee","what":"Chewy cylinder-shaped rice cakes in a thick, sweet-spicy red gochujang sauce, often with fish cakes and boiled egg. Korea's favourite street snack.","ingredients":["Rice cakes (tteok)","Gochujang chilli sauce","Fish cakes & boiled egg (often)","Spring onions"],"texture":["Very chewy","Saucy"],"goodFor":["Spicy food","Chewy textures","K-food"],"tip":"Try rosé (creamy) tteokbokki if spicy food scares you.","steps":[{"icon":"🥢","text":"Pick up one rice cake with chopsticks or a toothpick."},{"icon":"🔥","text":"Bite in half — they're hot."},{"icon":"🧀","text":"Too spicy? Order the cheese or rosé (creamy) version."},{"icon":"❓","text":"Veg? Ask — the sauce often uses anchovy stock and fish cakes."}],"reviews":{"rating":4.5,"summary":"Sweet, spicy and chewy — K-drama favourite. Spicy and chewy for beginners.","loved":["Sweet-spicy sauce","Chewy rice cakes"],"watch":["Quite spicy","Fish cakes & stock"],"samples":[{"name":"Minji","stars":5,"text":"Street tteokbokki with fish cake — comfort food."},{"name":"Ananya","stars":4,"text":"Rosé tteokbokki is perfect if you can't handle heat."},{"name":"Tom","stars":4,"text":"Chewy! Like thick gummy noodles."}]},"photo":{"src":"images/tteokbokki.jpg","title":"Tteokbokki.JPG","author":"Popo le Chien","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"https://commons.wikimedia.org/wiki/File:Tteokbokki.JPG","thumb":"images/thumb/tteokbokki.jpg"}},"gimbap":{"pron":"GIM-bahp","what":"Korean seaweed rice rolls filled with vegetables, egg and often ham or tuna, seasoned with sesame oil. Looks like sushi but has no raw fish.","ingredients":["Rice with sesame oil","Seaweed (gim)","Spinach, carrot, pickled radish","Egg","Ham / tuna / bulgogi (varies)"],"texture":["Soft rice","Crunchy veggies"],"goodFor":["Sushi","Rice rolls","Light meals"],"tip":"Scared of raw fish? Gimbap is fully cooked.","steps":[{"icon":"🤲","text":"Eat slices with chopsticks or fingers — one slice per bite."},{"icon":"🫗","text":"No soy sauce dipping needed; it's already seasoned."},{"icon":"🥢","text":"Pair with tteokbokki or soup."}],"reviews":{"rating":4.5,"summary":"Fresh, light and colourful. Many people's favourite picnic food.","loved":["Fresh & light","No raw fish"],"watch":["Usually has egg","Often has ham"],"samples":[{"name":"Jiwoo","stars":5,"text":"Tuna gimbap is my go-to lunch."},{"name":"Neha","stars":4,"text":"Like sushi but all cooked. Loved it."},{"name":"Owen","stars":4,"text":"Great with spicy tteokbokki."}]},"photo":{"src":"images/gimbap.jpg","title":"Vegetable gimbap.jpg","author":"cutekirin","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"https://commons.wikimedia.org/wiki/File:Vegetable_gimbap.jpg","thumb":"images/thumb/gimbap.jpg"}},"katsudon":{"pron":"KAHT-soo-don","what":"A rice bowl topped with a crispy breaded pork cutlet simmered with onion and soft egg in a sweet-savoury dashi sauce.","ingredients":["Pork cutlet (tonkatsu)","Egg","Onion","Dashi, soy, mirin","Rice"],"texture":["Crispy-soft cutlet","Silky egg","Fluffy rice"],"goodFor":["Rice bowls","Fried cutlets","Comfort food"],"tip":"Contains pork, egg and dashi (fish stock).","steps":[{"icon":"🥢","text":"Use chopsticks to pick up cutlet with some egg and rice."},{"icon":"🍚","text":"Lift the bowl close to your mouth — that's polite in Japan."},{"icon":"🥒","text":"Eat the pickles on the side between bites."}],"reviews":{"rating":4.6,"summary":"Hearty and comforting. Breading goes soft in the sauce.","loved":["Comforting","Sweet-savoury sauce"],"watch":["Pork","Soft breading"],"samples":[{"name":"Kenji","stars":5,"text":"Katsudon after exams — tradition!"},{"name":"Mia","stars":4,"text":"Pork cutlet + egg + rice = happiness."},{"name":"Arun","stars":4,"text":"Try chicken (chicken katsudon) if no pork."}]},"photo":{"src":"images/katsudon.jpg","title":"Katsudon 001.jpg","author":"Ocdp","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"https://commons.wikimedia.org/wiki/File:Katsudon_001.jpg","thumb":"images/thumb/katsudon.jpg"}},"gyudon":{"pron":"GYOO-don (beef bowl)","what":"A Japanese fast-food bowl of thinly sliced beef and onions simmered in sweet soy-dashi sauce over rice.","ingredients":["Thin beef slices","Onion","Soy sauce, mirin, dashi","Rice","Pickled ginger"],"texture":["Tender beef","Saucy rice"],"goodFor":["Rice bowls","Beef","Fast food"],"tip":"Popular chains: Yoshinoya, Sukiya, Matsuya.","steps":[{"icon":"🥢","text":"Eat with chopsticks, mixing beef and rice."},{"icon":"🥚","text":"Many add a raw or soft egg on top — stir it in."},{"icon":"🔴","text":"Add red pickled ginger and shichimi chili to taste."}],"reviews":{"rating":4.5,"summary":"Fast, cheap and satisfying. Simple flavour.","loved":["Quick & cheap","Sweet-savoury"],"watch":["Beef","Fatty slices"],"samples":[{"name":"Yuki","stars":5,"text":"Late-night gyudon at Yoshinoya."},{"name":"Paul","stars":4,"text":"Simple and satisfying."},{"name":"Sana","stars":4,"text":"Add pickled ginger."}]},"photo":{"src":"images/gyudon.jpg","title":"20220914燒丼株式會社-牛野郎丼XL.jpg","author":"迷惘的人生","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"https://commons.wikimedia.org/wiki/File:20220914%E7%87%92%E4%B8%BC%E6%A0%AA%E5%BC%8F%E6%9C%83%E7%A4%BE-%E7%89%9B%E9%87%8E%E9%83%8E%E4%B8%BCXL.jpg","thumb":"images/thumb/gyudon.jpg"}},"oyakodon":{"pron":"OH-yah-koh-don","what":"\"Parent-and-child bowl\" — chicken and egg simmered together in sweet dashi-soy sauce, served over rice.","ingredients":["Chicken thigh","Eggs","Onion","Dashi, soy, mirin","Rice"],"texture":["Soft","Silky egg"],"goodFor":["Rice bowls","Mild food","Chicken & egg"],"tip":"The name means \"parent and child\" — chicken and egg!","steps":[{"icon":"🥢","text":"Use chopsticks or a spoon."},{"icon":"🍚","text":"Eat chicken, egg and rice together."},{"icon":"🌿","text":"Add a sprinkle of mitsuba or shichimi."}],"reviews":{"rating":4.6,"summary":"Gentle, homely comfort food. Egg is often runny.","loved":["Comforting","Mild"],"watch":["Runny egg","Mild for some"],"samples":[{"name":"Haruka","stars":5,"text":"Mom's oyakodon is the best."},{"name":"Leo","stars":4,"text":"Like a silky chicken-egg rice bowl."},{"name":"Neha","stars":4,"text":"Very mild — good for kids."}]},"photo":{"src":"images/oyakodon.jpg","title":"Beef, grilled chicken and egg bowl of Matsuya.jpg","author":"毒島みるく","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"https://commons.wikimedia.org/wiki/File:Beef,_grilled_chicken_and_egg_bowl_of_Matsuya.jpg","thumb":"images/thumb/oyakodon.jpg"}},"omurice":{"pron":"OH-moo-rice","what":"Ketchup-flavoured fried rice (usually with chicken) wrapped in or topped with a soft omelette, finished with ketchup or demi-glace sauce.","ingredients":["Fried rice with chicken","Ketchup","Eggs","Butter","Demi-glace (optional)"],"texture":["Soft omelette","Fluffy rice"],"goodFor":["Omelettes","Fried rice","Kids"],"tip":"Usually has chicken in the rice — ask if they do a veg/egg-only version.","steps":[{"icon":"🔪","text":"If the omelette is on top, cut it open so it spreads over the rice."},{"icon":"🥄","text":"Eat with a spoon."},{"icon":"🍅","text":"Mix with the sauce."}],"reviews":{"rating":4.6,"summary":"Cute and comforting. Ketchup taste is sweet.","loved":["Fun to cut","Comforting"],"watch":["Sweet ketchup","Contains chicken"],"samples":[{"name":"Aiko","stars":5,"text":"Cutting the omelette is so satisfying."},{"name":"Sam","stars":4,"text":"Fried rice wrapped in egg — yum."},{"name":"Rina","stars":4,"text":"Demi-glace version is richer."}]},"photo":{"src":"images/omurice.jpg","title":"Omurice by Taimeiken.jpg","author":"Kanesue","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"https://commons.wikimedia.org/wiki/File:Omurice_by_Taimeiken.jpg","thumb":"images/thumb/omurice.jpg"}},"tonkatsu":{"pron":"TON-kaht-soo","what":"A thick pork cutlet coated in panko breadcrumbs and deep-fried until crisp, served sliced with shredded cabbage and a sweet-tangy tonkatsu sauce.","ingredients":["Pork loin or fillet","Panko breadcrumbs","Tonkatsu sauce","Cabbage","Rice & miso soup"],"texture":["Very crispy","Juicy"],"goodFor":["Fried cutlets","Schnitzel","Crispy food"],"tip":"\"Hire\" = lean fillet; \"rosu\" = loin with some fat.","steps":[{"icon":"🥢","text":"Pick up a slice with chopsticks."},{"icon":"🫗","text":"Dip in tonkatsu sauce (and mustard if you like)."},{"icon":"🥬","text":"Eat the cabbage with sesame dressing between bites."}],"reviews":{"rating":4.7,"summary":"Crispy, juicy and satisfying. Heavy.","loved":["Super crispy","Juicy"],"watch":["Pork","Fried"],"samples":[{"name":"Takumi","stars":5,"text":"Thick-cut tonkatsu is a treat."},{"name":"Jane","stars":4,"text":"Best fried pork I've had."},{"name":"Aditya","stars":4,"text":"Chicken katsu for no pork."}]},"photo":{"src":"images/tonkatsu.jpg","title":"Tonkatsu of Kimukatsu.jpg","author":"Minseong Kim","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"https://commons.wikimedia.org/wiki/File:Tonkatsu_of_Kimukatsu.jpg","thumb":"images/thumb/tonkatsu.jpg"}},"karaage":{"pron":"kah-RAH-ah-geh","what":"Japanese fried chicken — bite-sized pieces marinated in soy, ginger and garlic, coated in starch and deep-fried until crispy.","ingredients":["Chicken thigh","Soy sauce, ginger, garlic","Potato starch","Lemon","Mayo (optional)"],"texture":["Crispy","Juicy"],"goodFor":["Fried chicken","Bar snacks","Kids"],"tip":"In Japan, ask before squeezing lemon on a shared plate!","steps":[{"icon":"🍋","text":"Squeeze lemon over (ask first if sharing — it's a debate in Japan!)."},{"icon":"🥢","text":"Pick with chopsticks or fingers."},{"icon":"🫗","text":"Dip in Japanese mayo if offered."}],"reviews":{"rating":4.7,"summary":"Juicy, crispy and addictive. Great with drinks.","loved":["Juicy","Crispy"],"watch":["Fried","Hot inside"],"samples":[{"name":"Ren","stars":5,"text":"Karaage and beer at an izakaya."},{"name":"Chloe","stars":4,"text":"Best fried chicken bites."},{"name":"Vikram","stars":4,"text":"Lemon makes it better."}]},"photo":{"src":"images/karaage.jpg","title":"Shige Sushi and Izakaya - Nov 2019 - Stierch 02.jpg","author":"Missvain","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","source":"https://commons.wikimedia.org/wiki/File:Shige_Sushi_and_Izakaya_-_Nov_2019_-_Stierch_02.jpg","thumb":"images/thumb/karaage.jpg"}},"yakitori":{"pron":"YAH-kee-toh-ree","what":"Small skewers of chicken grilled over charcoal, seasoned either with salt (shio) or a sweet soy glaze (tare). Includes thigh, skin, meatballs and organs.","ingredients":["Chicken pieces","Spring onion (negima)","Tare sauce or salt","Shichimi pepper"],"texture":["Smoky","Juicy","Chewy (some parts)"],"goodFor":["Skewers","Grilled chicken","Bar snacks"],"tip":"Safe picks: momo (thigh), negima (thigh + leek), tsukune (meatball).","steps":[{"icon":"🍢","text":"Eat straight from the skewer."},{"icon":"🌶️","text":"Sprinkle shichimi pepper if you like."},{"icon":"🗑️","text":"Put empty skewers in the cup provided."}],"reviews":{"rating":4.6,"summary":"Smoky and great with drinks. Organ cuts are for the adventurous.","loved":["Smoky","Many choices"],"watch":["Organs on some menus","Small portions"],"samples":[{"name":"Hiro","stars":5,"text":"Tsukune with egg yolk dip — try it!"},{"name":"Mark","stars":4,"text":"Negima (thigh + leek) is my favourite."},{"name":"Shreya","stars":4,"text":"Ask which ones are plain meat."}]},"photo":{"src":"images/yakitori.jpg","title":"Cooking yakitori.jpg","author":"竹麦魚(Searobin)","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/","source":"https://commons.wikimedia.org/wiki/File:Cooking_yakitori.jpg","thumb":"images/thumb/yakitori.jpg"}},"yakisoba":{"pron":"YAH-kee-soh-bah","what":"Stir-fried wheat noodles with cabbage, pork or veggies and a thick sweet-tangy sauce, topped with seaweed powder and pickled ginger. A festival favourite.","ingredients":["Wheat noodles","Cabbage, carrot, onion","Pork (often)","Yakisoba sauce","Aonori, pickled ginger"],"texture":["Chewy noodles","Saucy"],"goodFor":["Noodles","Chow mein","Street food"],"tip":"Vegetarian? Ask for no pork — the sauce may still contain fish/anchovy (Worcestershire).","steps":[{"icon":"🥢","text":"Eat with chopsticks."},{"icon":"🍜","text":"Slurping is fine."},{"icon":"🔴","text":"Mix in pickled ginger for a zing."}],"reviews":{"rating":4.5,"summary":"Tasty street food. Sauce can be sweet.","loved":["Saucy & tasty","Street-food fun"],"watch":["Usually pork","Sweet sauce"],"samples":[{"name":"Sora","stars":5,"text":"Yakisoba at summer festivals."},{"name":"Ella","stars":4,"text":"Like Japanese chow mein."},{"name":"Ajay","stars":4,"text":"Ask for veg only."}]},"photo":{"src":"images/yakisoba.jpg","title":"Nagata Honjoken Bokkake Yakisoba.jpg","author":"Tokumeigakarinoaoshima","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"https://commons.wikimedia.org/wiki/File:Nagata_Honjoken_Bokkake_Yakisoba.jpg","thumb":"images/thumb/yakisoba.jpg"}},"okonomiyaki":{"pron":"oh-koh-noh-mee-YAH-kee","what":"A savoury Japanese pancake of cabbage and batter, cooked on a griddle and topped with sweet sauce, mayo, seaweed and dancing bonito flakes. \"Okonomi\" means \"as you like\".","ingredients":["Cabbage","Flour & egg batter","Pork / seafood (optional)","Okonomi sauce & mayo","Bonito flakes, aonori"],"texture":["Soft inside","Crisp edges"],"goodFor":["Pancakes","Street food","Pajeon"],"tip":"Contains egg; bonito topping is fish — ask to remove for veg.","steps":[{"icon":"🍳","text":"It's often cooked on a hot plate at your table — use the small spatula to cut a piece."},{"icon":"🥢","text":"Eat from the spatula or move it to your plate with chopsticks."},{"icon":"👀","text":"Bonito flakes \"dance\" from the heat — that's normal!"}],"reviews":{"rating":4.6,"summary":"Fun, filling and saucy. Bonito flakes (fish) are on top.","loved":["Fun to eat","Filling"],"watch":["Fish flakes on top","Heavy"],"samples":[{"name":"Naoko","stars":5,"text":"Osaka okonomiyaki — must try."},{"name":"Tom","stars":4,"text":"Cabbage pancake with everything on it."},{"name":"Divya","stars":4,"text":"Ask for no bonito and no pork."}]},"photo":{"src":"images/okonomiyaki.jpg","title":"Okonomiyaki 001.jpg","author":"ume-y","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"https://commons.wikimedia.org/wiki/File:Okonomiyaki_001.jpg","thumb":"images/thumb/okonomiyaki.jpg"}},"green-tea-ice-cream":{"pron":"MAH-chah ice cream","what":"Ice cream flavoured with matcha (powdered green tea). Creamy, lightly sweet and pleasantly bitter with a grassy tea flavour.","ingredients":["Milk & cream","Matcha green tea powder","Sugar"],"texture":["Creamy","Cold"],"goodFor":["Ice cream","Matcha lovers","Light desserts"],"tip":"Strict about egg? Some custard-based ice creams contain yolks — ask.","steps":[{"icon":"🥄","text":"Eat with a spoon or as a cone."},{"icon":"🍵","text":"Expect a slight bitterness — that's good matcha."},{"icon":"🫘","text":"Try it with red bean paste on the side."}],"reviews":{"rating":4.6,"summary":"Grown-up flavour. Bitterness surprises some.","loved":["Not too sweet","Unique flavour"],"watch":["Slightly bitter","May contain egg in custard bases"],"samples":[{"name":"Yui","stars":5,"text":"Kyoto matcha soft-serve — perfect."},{"name":"Ben","stars":3,"text":"A bit bitter, grew on me."},{"name":"Neha","stars":4,"text":"Lovely after sushi."}]},"photo":{"src":"images/green-tea-ice-cream.jpg","title":"Matcha ice cream 001.jpg","author":"City Foodsters","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"https://commons.wikimedia.org/wiki/File:Matcha_ice_cream_001.jpg","thumb":"images/thumb/green-tea-ice-cream.jpg"}},"edamame":{"pron":"eh-dah-MAH-meh","what":"Young green soybeans boiled in their pods and sprinkled with salt. A simple, healthy Japanese starter.","ingredients":["Young soybeans in pods","Sea salt","Garlic / chilli (some versions)"],"texture":["Firm","Slightly crunchy"],"goodFor":["Healthy snacks","Bar snacks","Vegans"],"tip":"Eat the beans, not the pods!","steps":[{"icon":"🫛","text":"Put the pod to your lips and squeeze or pull it through your teeth to pop out the beans."},{"icon":"🗑️","text":"Don't eat the pod — it's tough. Put empty pods in the side bowl."},{"icon":"🍺","text":"Great with drinks."}],"reviews":{"rating":4.5,"summary":"Healthy and moreish. Don't eat the pods!","loved":["Healthy","Fun to pop"],"watch":["Don't eat pods","Plain"],"samples":[{"name":"Taro","stars":5,"text":"Edamame and beer — the perfect start."},{"name":"Kim","stars":4,"text":"Popping beans is addictive."},{"name":"Ananya","stars":4,"text":"Try garlic-chilli edamame."}]},"photo":{"src":"images/edamame.jpg","title":"Edamame by Zesmerelda in Chicago.jpg","author":"Tammy Green (aka Zesmerelda) from Chicago Upscale Dining + Lounge Republic Pan-Asian Restaurant [1] in Ontario & Rush Street, Chicago, Illinois 60611","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"https://commons.wikimedia.org/wiki/File:Edamame_by_Zesmerelda_in_Chicago.jpg","thumb":"images/thumb/edamame.jpg"}},"shabu-shabu":{"pron":"SHAH-boo SHAH-boo","what":"A Japanese hot pot where you swish paper-thin slices of beef or pork in simmering broth at your table, then dip them in sesame or ponzu sauce.","ingredients":["Thin beef or pork slices","Kombu broth","Tofu, vegetables, mushrooms","Ponzu & sesame sauces","Noodles at the end"],"texture":["Tender","Light"],"goodFor":["Hot pot","Groups","Light meals"],"tip":"Swish beef just 2–3 times; cook pork fully.","steps":[{"icon":"🥢","text":"Hold a meat slice with chopsticks and swish it in the broth 2–3 times — \"shabu shabu\"!"},{"icon":"🫗","text":"Dip in ponzu (citrus) or goma (sesame) sauce."},{"icon":"🍜","text":"At the end, noodles or rice are cooked in the flavoured broth."}],"reviews":{"rating":4.6,"summary":"Fun, light and social. Cook meat fully, especially pork.","loved":["Interactive","Light & healthy"],"watch":["Cook it yourself","Mostly meat"],"samples":[{"name":"Hana","stars":5,"text":"Swish, dip, eat. Love it."},{"name":"Ryan","stars":4,"text":"Lighter than Korean BBQ."},{"name":"Arjun","stars":4,"text":"Veg sets exist at some places."}]},"photo":{"src":"images/shabu-shabu.jpg","title":"Shabu-shabu-01.jpg","author":"jimg944","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"https://commons.wikimedia.org/wiki/File:Shabu-shabu-01.jpg","thumb":"images/thumb/shabu-shabu.jpg"}},"jajangmyeon":{"pron":"JAH-jahng-myun","what":"Thick wheat noodles topped with a glossy black bean sauce cooked with pork, onions and zucchini. Korea's favourite delivery food.","ingredients":["Wheat noodles","Black bean paste (chunjang)","Pork","Onion, zucchini","Pickled radish"],"texture":["Chewy","Thick sauce"],"goodFor":["Noodles","Comfort food","Kids"],"tip":"Usually has pork — some places make a veg version.","steps":[{"icon":"🥢","text":"Mix the sauce into the noodles completely before eating."},{"icon":"🍜","text":"Slurp — it's messy and fun."},{"icon":"🟡","text":"Eat with yellow pickled radish."}],"reviews":{"rating":4.5,"summary":"Savoury-sweet and comforting. Black sauce stains!","loved":["Comforting","Rich sauce"],"watch":["Messy","Usually pork"],"samples":[{"name":"Jisoo","stars":5,"text":"Jajangmyeon after moving house — tradition."},{"name":"Mike","stars":4,"text":"Sweet-savoury black noodles."},{"name":"Ana","stars":4,"text":"Wear dark clothes!"}]},"photo":{"src":"images/jajangmyeon.jpg","title":"Jajangmyeon by stu spivack.jpg","author":"stu_spivack","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"https://commons.wikimedia.org/wiki/File:Jajangmyeon_by_stu_spivack.jpg","thumb":"images/thumb/jajangmyeon.jpg"}},"naengmyeon":{"pron":"NAENG-myun","what":"Ice-cold buckwheat noodles in a tangy chilled beef broth (mul) or spicy sauce (bibim), topped with sliced beef, egg, cucumber and pear.","ingredients":["Buckwheat noodles","Chilled beef broth","Beef slices, boiled egg","Cucumber, Korean pear","Vinegar & mustard"],"texture":["Very chewy","Icy"],"goodFor":["Cold noodles","Summer food","After BBQ"],"tip":"Noodles are very long — scissors are normal.","steps":[{"icon":"✂️","text":"Ask staff to cut the long, chewy noodles with scissors."},{"icon":"🫗","text":"Add vinegar and mustard to taste."},{"icon":"🥢","text":"Eat noodles and drink the icy broth."}],"reviews":{"rating":4.4,"summary":"Refreshing summer dish. Chewy texture and cold broth surprise some.","loved":["Refreshing","Summer favourite"],"watch":["Very chewy","Ice-cold"],"samples":[{"name":"Minho","stars":5,"text":"After Korean BBQ, mul naengmyeon!"},{"name":"Kate","stars":3,"text":"Cold noodle soup is unusual but refreshing."},{"name":"Dev","stars":4,"text":"Bibim version is spicy."}]},"photo":{"src":"images/naengmyeon.jpg","title":"Naengmyeon (cold noodles).jpg","author":"wjlee4284","license":"CC BY 2.5","licenseUrl":"https://creativecommons.org/licenses/by/2.5","source":"https://commons.wikimedia.org/wiki/File:Naengmyeon_(cold_noodles).jpg","thumb":"images/thumb/naengmyeon.jpg"}},"hotteok":{"pron":"HO-ttok","what":"A Korean street pancake filled with brown sugar, cinnamon and nuts that melt into a syrup inside as it fries.","ingredients":["Wheat/glutinous rice dough","Brown sugar","Cinnamon","Nuts & seeds"],"texture":["Crispy outside","Chewy","Syrupy"],"goodFor":["Street sweets","Pancakes","Winter"],"tip":"The filling is molten sugar — wait before biting.","steps":[{"icon":"🔥","text":"Wait a moment — the syrup inside is extremely hot."},{"icon":"📜","text":"Hold it in the paper cup they give you."},{"icon":"🦷","text":"Bite from the edge."}],"reviews":{"rating":4.6,"summary":"Sweet winter street treat. Hot syrup burns!","loved":["Gooey","Warm"],"watch":["Hot syrup","Sweet"],"samples":[{"name":"Seo","stars":5,"text":"Winter hotteok in Seoul."},{"name":"Liam","stars":4,"text":"Like a cinnamon sugar pancake."},{"name":"Ira","stars":4,"text":"Let it cool a bit first!"}]},"photo":{"src":"images/hotteok.jpg","title":"Hotteok.jpg","author":"Korea.net / Korean Culture and Information Service","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"https://commons.wikimedia.org/wiki/File:Hotteok.jpg","thumb":"images/thumb/hotteok.jpg"}},"samgyetang":{"pron":"SAHM-gyeh-tahng","what":"A whole young chicken stuffed with sticky rice, ginseng, jujubes and garlic, simmered in a light broth. Eaten in summer for energy.","ingredients":["Whole young chicken","Glutinous rice","Ginseng","Jujubes & garlic","Salt & pepper"],"texture":["Tender","Light broth"],"goodFor":["Chicken soup","Mild food","Healthy"],"tip":"It comes unsalted — season it yourself.","steps":[{"icon":"🧂","text":"Season the broth yourself with salt and pepper."},{"icon":"🥢","text":"Pull the chicken apart with chopsticks; scoop out the rice inside."},{"icon":"🦴","text":"Put bones in the empty bowl."}],"reviews":{"rating":4.5,"summary":"Healthy and gentle. Mild unless seasoned.","loved":["Healing","Gentle"],"watch":["Bones","Mild"],"samples":[{"name":"Jiwoo","stars":5,"text":"Samgyetang on the hottest day — tradition."},{"name":"Peter","stars":4,"text":"Whole chicken soup with ginseng."},{"name":"Kavi","stars":4,"text":"Add salt — it comes plain."}]},"photo":{"src":"images/samgyetang.jpg","title":"Samgye-tang 2.jpg","author":"wizdata","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"https://commons.wikimedia.org/wiki/File:Samgye-tang_2.jpg","thumb":"images/thumb/samgyetang.jpg"}},"sundubu-jjigae":{"pron":"SOON-doo-boo JJEE-geh","what":"A bubbling spicy stew of extra-soft silken tofu with seafood or pork, often with a raw egg cracked in at the table.","ingredients":["Silken tofu","Chilli paste & flakes","Seafood or pork (or veg)","Egg","Anchovy or vegetable broth"],"texture":["Silky tofu","Bubbling hot"],"goodFor":["Tofu","Stews","Spicy food"],"tip":"Usually has seafood/pork and anchovy broth — ask for a vegetable one.","steps":[{"icon":"🥚","text":"Crack the egg into the hot stew and let it cook."},{"icon":"🍚","text":"Eat spoonfuls with rice."},{"icon":"🔥","text":"It's served boiling — wait a moment."}],"reviews":{"rating":4.6,"summary":"Comforting and spicy. Very hot!","loved":["Silky tofu","Warming"],"watch":["Very hot","Seafood/egg often"],"samples":[{"name":"Hye","stars":5,"text":"Sundubu with rice on a cold day."},{"name":"Josh","stars":4,"text":"Spicy tofu stew, love it."},{"name":"Rhea","stars":4,"text":"Ask for veg broth."}]},"photo":{"src":"images/sundubu-jjigae.jpg","title":"Sundubu-jjigae.jpg","author":"행복한 초록개구리","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","source":"https://commons.wikimedia.org/wiki/File:Sundubu-jjigae.jpg","thumb":"images/thumb/sundubu-jjigae.jpg"}},"budae-jjigae":{"pron":"BOO-deh JJEE-geh (army stew)","what":"\"Army stew\" — a spicy hot pot of sausages, Spam, baked beans, kimchi, ramen noodles and cheese. Born from post-war Korea.","ingredients":["Sausages & Spam","Kimchi","Ramen noodles","Baked beans","Cheese slice & gochujang"],"texture":["Saucy","Chewy noodles"],"goodFor":["Hot pot","Groups","Ramen lovers"],"tip":"Order for 2+ people — it's a shared pot.","steps":[{"icon":"👥","text":"It's shared — cook it at the table."},{"icon":"🍜","text":"Wait until the ramen softens, then serve into your bowl."},{"icon":"🍚","text":"Eat with rice."}],"reviews":{"rating":4.5,"summary":"Fun, salty, spicy comfort food. Heavy and processed.","loved":["Fun to share","Comforting"],"watch":["Very salty","Processed meat"],"samples":[{"name":"Dongho","stars":5,"text":"Budae jjigae with friends — the best."},{"name":"Ellie","stars":4,"text":"Spam, ramen and cheese — guilty pleasure."},{"name":"Raj","stars":4,"text":"Great for groups."}]},"photo":{"src":"images/budae-jjigae.jpg","title":"Budae jjigae (28587380901).jpg","author":"T.Tseng","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"https://commons.wikimedia.org/wiki/File:Budae_jjigae_(28587380901).jpg","thumb":"images/thumb/budae-jjigae.jpg"}},"pajeon":{"pron":"PAH-jun","what":"A savoury Korean pancake loaded with spring onions, often with seafood (haemul pajeon). Crispy edges, dipped in soy-vinegar sauce.","ingredients":["Spring onions","Flour batter with egg","Seafood (optional)","Soy-vinegar dip"],"texture":["Crispy edges","Chewy middle"],"goodFor":["Pancakes","Sharing","Rainy days"],"tip":"Batter usually has egg; ask for no seafood for a veg-egg version.","steps":[{"icon":"✂️","text":"Cut it with scissors or chopsticks."},{"icon":"🫗","text":"Dip each piece in the soy sauce."},{"icon":"🍶","text":"Koreans love it with makgeolli, especially on rainy days."}],"reviews":{"rating":4.5,"summary":"Crispy and great for sharing. Oily.","loved":["Crispy","Great to share"],"watch":["Oily","Seafood version"],"samples":[{"name":"Minji","stars":5,"text":"Rainy day pajeon and makgeolli."},{"name":"Ryan","stars":4,"text":"Seafood pancake!"},{"name":"Sneha","stars":4,"text":"Ask for plain pa-jeon."}]},"photo":{"src":"images/pajeon.jpg","title":"Dongtae-jeon and donggeurang-ttaeng.jpg","author":"행복한 초록개구리","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","source":"https://commons.wikimedia.org/wiki/File:Dongtae-jeon_and_donggeurang-ttaeng.jpg","thumb":"images/thumb/pajeon.jpg"}},"kalguksu":{"pron":"KAHL-gook-soo","what":"Knife-cut wheat noodles in a mild, warm broth made from anchovy, clams or chicken, with zucchini and potato.","ingredients":["Knife-cut wheat noodles","Anchovy / clam / chicken broth","Zucchini, potato","Kimchi on side"],"texture":["Soft","Chewy"],"goodFor":["Noodle soups","Mild food","Comfort"],"tip":"Mild — add kimchi or chilli for a kick.","steps":[{"icon":"🥢","text":"Eat noodles with chopsticks, broth with a spoon."},{"icon":"🌶️","text":"Add the chilli sauce or eat with kimchi for heat."},{"icon":"🍜","text":"Slurping is fine."}],"reviews":{"rating":4.5,"summary":"Simple, comforting noodle soup.","loved":["Comforting","Mild"],"watch":["Mild","Seafood broth often"],"samples":[{"name":"Soyeon","stars":5,"text":"Myeongdong kalguksu!"},{"name":"Will","stars":4,"text":"Comforting noodle soup."},{"name":"Ram","stars":4,"text":"Kimchi on the side is key."}]},"photo":{"src":"images/kalguksu.jpg","title":"Haemul-kal-guksu.jpg","author":"행복한 초록개구리","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","source":"https://commons.wikimedia.org/wiki/File:Haemul-kal-guksu.jpg","thumb":"images/thumb/kalguksu.jpg"}},"tteokguk":{"pron":"TTUK-gook (rice cake soup)","what":"A light beef broth with sliced chewy rice cakes, egg strips and seaweed. Eaten on Lunar New Year — legend says you gain a year of age!","ingredients":["Sliced rice cakes","Beef broth","Egg strips","Seaweed","Spring onion"],"texture":["Chewy","Light broth"],"goodFor":["Soups","Mild food","Chewy textures"],"tip":"Contains beef broth and egg.","steps":[{"icon":"🥄","text":"Eat with a spoon."},{"icon":"🥢","text":"Use chopsticks for rice cakes."},{"icon":"🎉","text":"Eat it on New Year for luck."}],"reviews":{"rating":4.5,"summary":"Gentle and festive. Very mild.","loved":["Festive","Gentle"],"watch":["Mild","Chewy"],"samples":[{"name":"Jae","stars":5,"text":"New Year tteokguk — one year older!"},{"name":"Amy","stars":4,"text":"Chewy rice cake soup."},{"name":"Neel","stars":4,"text":"Light and clean."}]},"photo":{"src":"images/tteokguk.jpg","title":"Tteokguk.jpg","author":"soscs","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"https://commons.wikimedia.org/wiki/File:Tteokguk.jpg","thumb":"images/thumb/tteokguk.jpg"}},"japchae":{"pron":"JAHP-cheh","what":"Glass noodles made from sweet potato, stir-fried with vegetables, beef and sesame oil in a sweet soy sauce. Served at Korean celebrations.","ingredients":["Sweet potato glass noodles","Spinach, carrot, mushroom","Beef (optional)","Soy & sesame oil","Egg strips"],"texture":["Chewy","Slippery"],"goodFor":["Mild food","Glass noodles","Kids"],"tip":"Ask for no beef and no egg for a veg version.","steps":[{"icon":"🥢","text":"Pick up with chopsticks."},{"icon":"🍚","text":"Side dish or main."},{"icon":"✂️","text":"Ask staff to cut long noodles."}],"reviews":{"rating":4.6,"summary":"Sweet-savoury and mild.","loved":["Mild","Gluten-free noodles"],"watch":["Often beef","Oily"],"samples":[{"name":"Minji","stars":5,"text":"Mom's japchae on holidays."},{"name":"Paul","stars":4,"text":"Chewy sesame noodles."},{"name":"Lata","stars":4,"text":"Ask for veg."}]},"photo":{"src":"images/japchae.jpg","title":"Polish Korean Cuisine and Culture Exchanges Gradmother’s Recipes 05.jpg","author":"korea.net","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"https://commons.wikimedia.org/wiki/File:Polish_Korean_Cuisine_and_Culture_Exchanges_Gradmother%E2%80%99s_Recipes_05.jpg","thumb":"images/thumb/japchae.jpg"}},"mandu":{"pron":"MAHN-doo","what":"Korean dumplings filled with pork, tofu, glass noodles, kimchi or vegetables. Steamed, boiled or pan-fried.","ingredients":["Wheat wrapper","Pork / tofu / kimchi","Glass noodles","Garlic, spring onion","Soy-vinegar dip"],"texture":["Juicy","Crispy (fried)"],"goodFor":["Dumplings","Momos fans","Snacks"],"tip":"\"Gun-mandu\" = pan-fried; \"jjin-mandu\" = steamed.","steps":[{"icon":"🥢","text":"Pick up with chopsticks."},{"icon":"🫗","text":"Dip in soy-vinegar."},{"icon":"🌶️","text":"Kimchi mandu is spicy."}],"reviews":{"rating":4.6,"summary":"Juicy and comforting.","loved":["Juicy","Variety"],"watch":["Fillings vary","Hot inside"],"samples":[{"name":"Hyun","stars":5,"text":"Kimchi mandu!"},{"name":"Ella","stars":4,"text":"Like gyoza, bigger."},{"name":"Anil","stars":4,"text":"Veg mandu is great."}]},"photo":{"src":"images/mandu.jpg","title":"Jjinmandu (steamed dumplings).jpg","author":"국립국어원","license":"CC BY-SA 2.0 kr","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0/kr/deed.en","source":"https://commons.wikimedia.org/wiki/File:Jjinmandu_(steamed_dumplings).jpg","thumb":"images/thumb/mandu.jpg"}},"korokke":{"pron":"koh-ROH-keh","what":"Japanese croquettes of mashed potato mixed with minced meat or vegetables, coated in panko and deep-fried. Cheap butcher-shop snack.","ingredients":["Mashed potato","Minced beef or veg","Onion","Panko crumbs","Tonkatsu sauce"],"texture":["Crispy","Creamy"],"goodFor":["Aloo tikki fans","Croquettes","Snacks"],"tip":"Like a Japanese aloo tikki in panko.","steps":[{"icon":"🫗","text":"Drizzle tonkatsu sauce."},{"icon":"🥢","text":"Eat with chopsticks or in a bun."},{"icon":"🔥","text":"Hot inside!"}],"reviews":{"rating":4.5,"summary":"Crispy comfort snack.","loved":["Crispy","Cheap"],"watch":["Fried","Often has meat"],"samples":[{"name":"Yuta","stars":5,"text":"Butcher shop korokke!"},{"name":"Amy","stars":4,"text":"Like a crispy aloo tikki."},{"name":"Ravi","stars":4,"text":"Ask for potato only."}]},"photo":{"src":"images/korokke.jpg","title":"Potato croquettes 001.jpg","author":"Ocdp","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"https://commons.wikimedia.org/wiki/File:Potato_croquettes_001.jpg","thumb":"images/thumb/korokke.jpg"}},"tonkotsu-ramen":{"pron":"TON-koh-tsoo RAH-men","what":"Ramen in a creamy, milky pork-bone broth simmered for hours, with thin noodles, chashu pork, egg, spring onion and pickled ginger.","ingredients":["Pork bone broth","Thin noodles","Chashu pork","Soft-boiled egg","Spring onion, beni shoga"],"texture":["Creamy","Rich"],"goodFor":["Ramen lovers","Rich food","Pork lovers"],"tip":"Choose noodle firmness: \"katame\" = firm.","steps":[{"icon":"🍜","text":"Slurp — it's polite in Japan."},{"icon":"🥄","text":"Drink broth with the spoon."},{"icon":"🍥","text":"Order \"kaedama\" (extra noodles) if hungry."}],"reviews":{"rating":4.7,"summary":"Rich and satisfying.","loved":["Creamy broth","Rich"],"watch":["Pork","Heavy"],"samples":[{"name":"Kenta","stars":5,"text":"Ichiran in Fukuoka!"},{"name":"Ann","stars":4,"text":"Rich creamy broth."},{"name":"Sahil","stars":3,"text":"Very heavy."}]},"photo":{"src":"images/tonkotsu-ramen.jpg","title":"Tonkotsu ramen.JPG","author":"No machine-readable author provided. Schellack assumed (based on copyright claims).","license":"Public domain","licenseUrl":"","source":"https://commons.wikimedia.org/wiki/File:Tonkotsu_ramen.JPG","thumb":"images/thumb/tonkotsu-ramen.jpg"}},"tsukemen":{"pron":"TSOO-keh-men","what":"\"Dipping ramen\" — thick cold noodles served separately with a rich, concentrated hot broth to dip them in.","ingredients":["Thick noodles","Rich dipping broth (pork/fish)","Chashu","Egg","Nori"],"texture":["Chewy","Rich"],"goodFor":["Ramen lovers","Noodles","Bold flavours"],"tip":"Don't drink the dip straight — it's concentrated.","steps":[{"icon":"🥢","text":"Dip a bite of noodles into the broth."},{"icon":"🍜","text":"Slurp."},{"icon":"🫖","text":"At the end, ask for \"soup wari\" to dilute broth and drink it."}],"reviews":{"rating":4.6,"summary":"Intense and fun.","loved":["Chewy noodles","Intense broth"],"watch":["Salty broth","Pork & fish"],"samples":[{"name":"Takeshi","stars":5,"text":"Rokurinsha tsukemen!"},{"name":"Lea","stars":4,"text":"Dip-and-slurp is fun."},{"name":"Rahul","stars":4,"text":"Ask for soup wari."}]},"photo":{"src":"images/tsukemen.jpg","title":"Tsukemen at a Tokyo restaurant.jpg","author":"City Foodsters","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"https://commons.wikimedia.org/wiki/File:Tsukemen_at_a_Tokyo_restaurant.jpg","thumb":"images/thumb/tsukemen.jpg"}},"yaki-udon":{"pron":"YAH-kee OO-don","what":"Thick chewy udon noodles stir-fried with vegetables, meat or seafood and soy-based sauce, topped with bonito flakes.","ingredients":["Udon noodles","Cabbage, onion, carrot","Pork / chicken / seafood","Soy sauce","Bonito flakes"],"texture":["Very chewy","Saucy"],"goodFor":["Noodles","Stir-fries","Udon fans"],"tip":"Bonito on top is fish — ask to skip for veg.","steps":[{"icon":"🥢","text":"Eat with chopsticks."},{"icon":"🌶️","text":"Add shichimi."},{"icon":"🍜","text":"Slurp."}],"reviews":{"rating":4.5,"summary":"Hearty stir-fry.","loved":["Chewy","Hearty"],"watch":["Bonito flakes","Oily"],"samples":[{"name":"Sora","stars":5,"text":"Yaki udon at an izakaya."},{"name":"Mike","stars":4,"text":"Chunky noodles!"},{"name":"Neha","stars":4,"text":"Ask for no bonito."}]},"photo":{"src":"images/yaki-udon.jpg","title":"Yakiudon-tako.jpg","author":"投稿者","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"https://commons.wikimedia.org/wiki/File:Yakiudon-tako.jpg","thumb":"images/thumb/yaki-udon.jpg"}},"jjamppong":{"pron":"JJAHM-pong","what":"Spicy red seafood noodle soup with mussels, squid, shrimp and vegetables in a fiery chilli broth. Often ordered with jajangmyeon.","ingredients":["Wheat noodles","Seafood (mussels, squid, shrimp)","Chilli oil broth","Cabbage, onion","Pork (some)"],"texture":["Chewy","Brothy"],"goodFor":["Spicy food","Seafood","Noodle soups"],"tip":"Can't decide? Order \"jjamjjamyeon\" — half jajang, half jjamppong.","steps":[{"icon":"🥢","text":"Eat noodles first."},{"icon":"🦪","text":"Open mussels with chopsticks."},{"icon":"🥤","text":"Keep water handy."}],"reviews":{"rating":4.5,"summary":"Fiery and seafoody.","loved":["Spicy","Lots of seafood"],"watch":["Very spicy","Shellfish"],"samples":[{"name":"Jiho","stars":5,"text":"Jjamppong after drinks!"},{"name":"Chris","stars":3,"text":"Very spicy."},{"name":"Ravi","stars":4,"text":"Seafood lovers' dream."}]},"photo":{"src":"images/jjamppong.jpg","title":"Jjampong.JPG","author":"Alfpooh","license":"Public domain","licenseUrl":"","source":"https://commons.wikimedia.org/wiki/File:Jjampong.JPG","thumb":"images/thumb/jjamppong.jpg"}},"bibim-guksu":{"pron":"BEE-bim GOOK-soo","what":"Cold thin wheat noodles mixed with a sweet, spicy and tangy gochujang sauce, topped with cucumber, kimchi and a boiled egg.","ingredients":["Thin wheat noodles","Gochujang sauce","Vinegar & sugar","Cucumber, kimchi","Boiled egg"],"texture":["Cold","Chewy"],"goodFor":["Cold noodles","Spicy food","Summer"],"tip":"Kimchi often contains fish sauce — ask if strict veg.","steps":[{"icon":"🥢","text":"Mix well with chopsticks."},{"icon":"🥒","text":"Eat with cucumber."},{"icon":"🍜","text":"Slurp."}],"reviews":{"rating":4.5,"summary":"Refreshing summer noodles.","loved":["Sweet-spicy","Refreshing"],"watch":["Kimchi may have fish sauce","Spicy"],"samples":[{"name":"Sunhee","stars":5,"text":"Summer bibim guksu."},{"name":"Adam","stars":4,"text":"Sweet spicy cold noodles."},{"name":"Arya","stars":4,"text":"Refreshing!"}]},"photo":{"src":"images/bibim-guksu.jpg","title":"Bibim-guksu.jpg","author":"JeongHO Suh (daecheonnet)","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"https://commons.wikimedia.org/wiki/File:Bibim-guksu.jpg","thumb":"images/thumb/bibim-guksu.jpg"}},"somen":{"pron":"SOH-men","what":"Very thin white wheat noodles served ice-cold with a light dipping sauce (tsuyu), ginger and spring onion. A Japanese summer favourite.","ingredients":["Thin wheat noodles","Ice water","Tsuyu dip (dashi, soy, mirin)","Ginger, spring onion"],"texture":["Silky","Cold"],"goodFor":["Light meals","Summer","Mild food"],"tip":"The dip usually contains dashi (fish stock).","steps":[{"icon":"🥢","text":"Pick up a small bundle."},{"icon":"🫗","text":"Dip in tsuyu."},{"icon":"🍜","text":"Slurp."}],"reviews":{"rating":4.4,"summary":"Light and refreshing.","loved":["Light","Refreshing"],"watch":["Mild","Dashi (fish) dip"],"samples":[{"name":"Mio","stars":5,"text":"Summer somen!"},{"name":"Sam","stars":4,"text":"Light cold noodles."},{"name":"Lata","stars":3,"text":"Dip has fish stock."}]},"photo":{"src":"images/somen.jpg","title":"Somen is wonderfully refreshing summer noodle in Japan.jpg","author":"Blue Lotus from Tokyo","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"https://commons.wikimedia.org/wiki/File:Somen_is_wonderfully_refreshing_summer_noodle_in_Japan.jpg","thumb":"images/thumb/somen.jpg"}},"dango":{"pron":"DAHN-goh","what":"Chewy rice-flour dumplings on a skewer, glazed with sweet soy syrup (mitarashi) or topped with red bean paste.","ingredients":["Rice flour","Sweet soy glaze or red bean","Skewer"],"texture":["Chewy","Sticky"],"goodFor":["Mochi fans","Tea time","Japanese sweets"],"tip":"\"Hanami dango\" is pink, white and green.","steps":[{"icon":"🍡","text":"Eat off the skewer."},{"icon":"🍵","text":"With green tea."},{"icon":"🦷","text":"Chew well."}],"reviews":{"rating":4.5,"summary":"Cute and chewy.","loved":["Chewy","Cute"],"watch":["Sticky","Choking risk for kids"],"samples":[{"name":"Hana","stars":5,"text":"Mitarashi dango in Kyoto."},{"name":"Jack","stars":4,"text":"Sweet soy mochi balls."},{"name":"Rina","stars":4,"text":"Chewy!"}]},"photo":{"src":"images/dango.jpg","title":"Mitarashi dango by denver935.jpg","author":"denver935","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"https://commons.wikimedia.org/wiki/File:Mitarashi_dango_by_denver935.jpg","thumb":"images/thumb/dango.jpg"}},"injeolmi":{"pron":"in-JUL-mee","what":"Chewy Korean rice cakes coated in roasted soybean powder. Nutty, lightly sweet.","ingredients":["Glutinous rice","Roasted soybean powder","Sugar","Salt"],"texture":["Chewy","Powdery"],"goodFor":["Mochi fans","Light sweets","Tea time"],"tip":"Try injeolmi bingsu (shaved ice) in summer.","steps":[{"icon":"🥢","text":"Pick up with a toothpick."},{"icon":"🍵","text":"With tea."},{"icon":"😮‍💨","text":"Don't breathe in the powder!"}],"reviews":{"rating":4.4,"summary":"Nutty and soft.","loved":["Nutty","Not too sweet"],"watch":["Powdery","Chewy"],"samples":[{"name":"Eunji","stars":5,"text":"Injeolmi bingsu!"},{"name":"Ella","stars":4,"text":"Nutty mochi."},{"name":"Kirti","stars":4,"text":"Light sweet."}]},"photo":{"src":"images/injeolmi.jpg","title":"Injeolmi (tteok) (rice cake).jpg","author":"LeeSeungHwan","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"https://commons.wikimedia.org/wiki/File:Injeolmi_(tteok)_(rice_cake).jpg","thumb":"images/thumb/injeolmi.jpg"}},"songpyeon":{"pron":"SONG-pyun","what":"Half-moon rice cakes filled with sesame-honey, beans or chestnut, steamed on pine needles. Made for Chuseok (Korean harvest festival).","ingredients":["Rice flour dough","Sesame & honey / beans","Pine needles (for steaming)"],"texture":["Chewy","Soft"],"goodFor":["Festive","Mochi fans","Light sweets"],"tip":"Like South Indian kozhukkatta in shape and idea.","steps":[{"icon":"✋","text":"Eat one bite at a time."},{"icon":"🍃","text":"Pine needles are for aroma — don't eat."},{"icon":"🍵","text":"Pair with tea."}],"reviews":{"rating":4.4,"summary":"Festive and pretty.","loved":["Festive","Pretty colours"],"watch":["Chewy","Mild"],"samples":[{"name":"Dahye","stars":5,"text":"Chuseok songpyeon!"},{"name":"Leo","stars":4,"text":"Pretty rice cakes."},{"name":"Asha","stars":4,"text":"Like kozhukkatta!"}]},"photo":{"src":"images/songpyeon.jpg","title":"Songpyeon.jpg","author":"wizdata","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"https://commons.wikimedia.org/wiki/File:Songpyeon.jpg","thumb":"images/thumb/songpyeon.jpg"}},"tteok":{"pron":"TTUK (Korean rice cakes)","what":"The general name for Korean rice cakes — steamed, pounded or shaped glutinous rice in many colours and fillings. Sweet or savoury.","ingredients":["Rice flour or glutinous rice","Fillings (beans, sesame)","Coatings"],"texture":["Chewy","Soft"],"goodFor":["Mochi fans","Light sweets","Gifts"],"tip":"Tteokbokki uses savoury tteok — different dish.","steps":[{"icon":"✋","text":"Pick one."},{"icon":"🍵","text":"With tea."},{"icon":"🦷","text":"Chew well."}],"reviews":{"rating":4.4,"summary":"Traditional and chewy.","loved":["Variety","Chewy"],"watch":["Chewy","Mild"],"samples":[{"name":"Jiwon","stars":5,"text":"Tteok shop treats."},{"name":"Sam","stars":4,"text":"Like Korean mochi."},{"name":"Rhea","stars":4,"text":"Try several."}]},"photo":{"src":"images/tteok.jpg","title":"Tteok.jpg","author":"user:takoradee","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"https://commons.wikimedia.org/wiki/File:Tteok.jpg","thumb":"images/thumb/tteok.jpg"}},"miso-soup":{"pron":"MEE-soh soup","what":"Japanese soup of dashi broth with dissolved miso paste, tofu, seaweed and spring onion. Served with most Japanese meals.","ingredients":["Dashi (bonito/kelp broth)","Miso paste","Tofu","Wakame seaweed","Spring onion"],"texture":["Light","Silky tofu"],"goodFor":["Light meals","Soups","Japanese food"],"tip":"Usually made with fish stock — ask for kombu dashi if veg.","steps":[{"icon":"🥣","text":"Drink straight from the bowl."},{"icon":"🥢","text":"Use chopsticks for tofu and seaweed."},{"icon":"🔄","text":"Stir — miso settles."}],"reviews":{"rating":4.5,"summary":"Comforting, simple.","loved":["Comforting","Light"],"watch":["Fish-based dashi","Salty"],"samples":[{"name":"Yuko","stars":5,"text":"Every Japanese meal."},{"name":"Tom","stars":4,"text":"Warm and simple."},{"name":"Divya","stars":3,"text":"Has fish stock!"}]},"photo":{"src":"images/miso-soup.jpg","title":"Miso Soup 001.jpg","author":"Ocdp","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"https://commons.wikimedia.org/wiki/File:Miso_Soup_001.jpg","thumb":"images/thumb/miso-soup.jpg"}},"tamagoyaki":{"pron":"tah-mah-GOH-yah-kee","what":"A sweet-savoury Japanese rolled omelette made by layering thin egg sheets in a rectangular pan. Bento and sushi favourite.","ingredients":["Eggs","Sugar","Soy & mirin","Dashi (often)"],"texture":["Soft","Layered"],"goodFor":["Egg lovers","Kids","Bento"],"tip":"Often has dashi (fish stock).","steps":[{"icon":"🥢","text":"Pick a slice with chopsticks."},{"icon":"🫗","text":"Dip in a little soy."},{"icon":"🍱","text":"Eat as part of bento."}],"reviews":{"rating":4.5,"summary":"Sweet, fluffy omelette.","loved":["Sweet","Fluffy"],"watch":["Contains egg","Dashi (fish)"],"samples":[{"name":"Rin","stars":5,"text":"Bento favourite."},{"name":"Ken","stars":4,"text":"Sweet egg roll!"},{"name":"Sana","stars":4,"text":"Kids love it."}]},"photo":{"src":"images/tamagoyaki.jpg","title":"鳥焼き居酒屋 (39394233682).jpg","author":"極地狐","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"https://commons.wikimedia.org/wiki/File:%E9%B3%A5%E7%84%BC%E3%81%8D%E5%B1%85%E9%85%92%E5%B1%8B_(39394233682).jpg","thumb":"images/thumb/tamagoyaki.jpg"}},"chawanmushi":{"pron":"chah-WAHN-moo-shee","what":"A silky, savoury steamed egg custard with dashi, shrimp, chicken, mushroom and ginkgo nuts, served in a cup.","ingredients":["Eggs","Dashi","Shrimp, chicken","Mushroom","Ginkgo nut"],"texture":["Silky","Wobbly"],"goodFor":["Mild food","Egg lovers","Soups"],"tip":"It's savoury — not a dessert.","steps":[{"icon":"🥄","text":"Eat with a small spoon."},{"icon":"🔥","text":"It's hot."},{"icon":"🍄","text":"Find treasures at the bottom."}],"reviews":{"rating":4.5,"summary":"Delicate and comforting.","loved":["Silky","Delicate"],"watch":["Savoury custard surprises","Egg & seafood"],"samples":[{"name":"Mayu","stars":5,"text":"Silky perfection."},{"name":"Ben","stars":4,"text":"Savoury pudding!"},{"name":"Ankit","stars":3,"text":"Unexpected texture."}]},"photo":{"src":"images/chawanmushi.jpg","title":"Chawan-mushi.JPG","author":"Brücke-Osteuropa","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"https://commons.wikimedia.org/wiki/File:Chawan-mushi.JPG","thumb":"images/thumb/chawanmushi.jpg"}},"sukiyaki":{"pron":"SOO-kee-yah-kee","what":"A hot pot of thinly sliced beef cooked at the table in sweet soy broth with tofu, vegetables and noodles, then dipped in raw beaten egg.","ingredients":["Thin beef slices","Sweet soy broth (warishita)","Tofu, leek, mushroom","Shirataki noodles","Raw egg dip"],"texture":["Tender","Saucy"],"goodFor":["Hot pot","Groups","Beef lovers"],"tip":"Raw egg dip is optional — ask to skip.","steps":[{"icon":"🍲","text":"Cook beef briefly in the broth."},{"icon":"🥚","text":"Dip in raw beaten egg."},{"icon":"🍚","text":"Eat with rice."}],"reviews":{"rating":4.6,"summary":"Sweet, rich and social.","loved":["Sweet-savoury","Social"],"watch":["Raw egg dip","Beef"],"samples":[{"name":"Akio","stars":5,"text":"New Year sukiyaki."},{"name":"Lisa","stars":4,"text":"Raw egg dip — try it!"},{"name":"Neel","stars":3,"text":"Skip egg if unsure."}]},"photo":{"src":"images/sukiyaki.jpg","title":"Sukiyaki 01.jpg","author":"ajari","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"https://commons.wikimedia.org/wiki/File:Sukiyaki_01.jpg","thumb":"images/thumb/sukiyaki.jpg"}},"daifuku":{"pron":"DIE-foo-koo","what":"Soft, round mochi filled with sweet red bean paste. Ichigo daifuku also has a whole strawberry inside.","ingredients":["Mochi (glutinous rice)","Red bean paste","Strawberry (ichigo)","Potato starch dusting"],"texture":["Soft","Chewy"],"goodFor":["Mochi fans","Light sweets","Tea time"],"tip":"Daifuku is a type of mochi.","steps":[{"icon":"✋","text":"Hold it and bite."},{"icon":"🍓","text":"Ichigo: see the strawberry cross-section."},{"icon":"🍵","text":"With green tea."}],"reviews":{"rating":4.6,"summary":"Soft and lovely.","loved":["Soft","Fresh fruit version"],"watch":["Chewy","Choking risk"],"samples":[{"name":"Sakura","stars":5,"text":"Ichigo daifuku in spring!"},{"name":"Tom","stars":4,"text":"Mochi with bean filling."},{"name":"Ana","stars":4,"text":"Strawberry one is best."}]},"photo":{"src":"images/daifuku.jpg","title":"Daifuku 1.jpg","author":"No machine-readable author provided. Lyzzy assumed (based on copyright claims).","license":"CC BY 2.5","licenseUrl":"https://creativecommons.org/licenses/by/2.5","source":"https://commons.wikimedia.org/wiki/File:Daifuku_1.jpg","thumb":"images/thumb/daifuku.jpg"}},"oden":{"pron":"OH-den","what":"A winter one-pot of fish cakes, daikon, boiled eggs, konjac and tofu simmered in light dashi broth. Sold at convenience stores and stalls.","ingredients":["Fish cakes","Daikon radish","Boiled eggs","Konjac","Dashi broth"],"texture":["Soft","Bouncy"],"goodFor":["Winter","Soups","Adventurous"],"tip":"Daikon soaked in broth is the favourite.","steps":[{"icon":"🍢","text":"Pick items you like."},{"icon":"🟡","text":"Add karashi mustard."},{"icon":"🥣","text":"Sip the broth."}],"reviews":{"rating":4.4,"summary":"Warm winter comfort.","loved":["Warming","Pick-your-own"],"watch":["Fish cakes","Konjac texture"],"samples":[{"name":"Daiki","stars":5,"text":"7-Eleven oden in winter!"},{"name":"Clara","stars":4,"text":"Fish cake stew."},{"name":"Rajat","stars":3,"text":"Konjac is odd."}]},"photo":{"src":"images/oden.jpg","title":"Yataioden.jpg","author":"Hykw-a4","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/","source":"https://commons.wikimedia.org/wiki/File:Yataioden.jpg","thumb":"images/thumb/oden.jpg"}},"inarizushi":{"pron":"ee-NAH-ree-zoo-shee","what":"Sweet, fried tofu pouches stuffed with sushi rice. Simple, sweet and veggie-friendly sushi.","ingredients":["Fried tofu pouch (aburaage)","Sushi rice","Sweet soy-dashi (sometimes)"],"texture":["Soft","Juicy"],"goodFor":["Sushi beginners","Vegetarians","Sweet tooth"],"tip":"Pouches may be simmered in fish dashi — ask if strict veg.","steps":[{"icon":"✋","text":"Eat by hand in one or two bites."},{"icon":"🫗","text":"No soy needed."},{"icon":"🍣","text":"Pair with other sushi."}],"reviews":{"rating":4.5,"summary":"Sweet and mild.","loved":["Sweet","Veg-friendly"],"watch":["Sweet for some","May contain dashi"],"samples":[{"name":"Aya","stars":5,"text":"Picnic inari!"},{"name":"Ben","stars":4,"text":"Sweet tofu sushi."},{"name":"Pooja","stars":4,"text":"Good veg sushi."}]},"photo":{"src":"images/inarizushi.jpg","title":"Kantofu Inarizushi.jpg","author":"Ocdp","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"https://commons.wikimedia.org/wiki/File:Kantofu_Inarizushi.jpg","thumb":"images/thumb/inarizushi.jpg"}},"andong-jjimdak":{"pron":"AHN-dong JJIM-dahk","what":"Braised chicken with glass noodles, potatoes, carrots and chillies in a sweet-savoury soy sauce. From Andong city.","ingredients":["Chicken","Glass noodles","Potato, carrot","Soy sauce","Dried chillies"],"texture":["Tender","Chewy noodles"],"goodFor":["Groups","Chicken","Comfort food"],"tip":"Order for 2+ people.","steps":[{"icon":"🍲","text":"It's shared — serve into your bowl."},{"icon":"🍚","text":"Eat with rice."},{"icon":"🍜","text":"Grab the noodles before they're gone!"}],"reviews":{"rating":4.6,"summary":"Comforting, sweet-spicy.","loved":["Sweet-savoury","Shareable"],"watch":["Spicy chillies","Bones"],"samples":[{"name":"Soojin","stars":5,"text":"Andong jjimdak!"},{"name":"Matt","stars":4,"text":"Soy chicken + noodles."},{"name":"Asha","stars":4,"text":"Great for groups."}]},"photo":{"src":"images/andong-jjimdak.jpg","title":"Jjimdak.jpg","author":"Debbie Tingzon","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"https://commons.wikimedia.org/wiki/File:Jjimdak.jpg","thumb":"images/thumb/andong-jjimdak.jpg"}},"california-roll":{"pron":"California roll","what":"An inside-out sushi roll with imitation crab, avocado and cucumber, rice on the outside often coated in sesame or fish roe. A beginner sushi.","ingredients":["Sushi rice","Imitation crab (surimi)","Avocado","Cucumber","Sesame or fish roe"],"texture":["Creamy","Soft"],"goodFor":["Sushi beginners","Mild food","Kids"],"tip":"No raw fish — a safe first sushi.","steps":[{"icon":"🥢","text":"Pick a piece with chopsticks or fingers."},{"icon":"🫗","text":"Dip lightly in soy."},{"icon":"🟢","text":"Add a little wasabi if you like."}],"reviews":{"rating":4.5,"summary":"Great first sushi.","loved":["Beginner-friendly","No raw fish"],"watch":["Imitation crab","Mild"],"samples":[{"name":"Jenna","stars":5,"text":"My gateway sushi!"},{"name":"Raju","stars":4,"text":"No raw fish — good."},{"name":"Kenji","stars":3,"text":"Not traditional, but tasty."}]},"photo":{"src":"images/california-roll.jpg","title":"California Sushi mit Kaviar (26545022496).jpg","author":"Tim Reckmann from Hamm, Deutschland","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"https://commons.wikimedia.org/wiki/File:California_Sushi_mit_Kaviar_(26545022496).jpg","thumb":"images/thumb/california-roll.jpg"}},"coffee-jelly":{"pron":"coffee jelly","what":"Cubes of firm coffee-flavoured jelly served with cream or milk. A popular Japanese café dessert.","ingredients":["Coffee","Sugar","Gelatin or agar","Cream / milk"],"texture":["Jiggly","Creamy"],"goodFor":["Coffee lovers","Light desserts","Café"],"tip":"Gelatin isn't vegetarian — ask for agar version.","steps":[{"icon":"🥄","text":"Eat with a spoon, mixing in the cream."},{"icon":"🥤","text":"Also served in drinks."},{"icon":"❄️","text":"Served cold."}],"reviews":{"rating":4.4,"summary":"Light coffee dessert.","loved":["Light","Not too sweet"],"watch":["Bitter","Gelatin (not veg)"],"samples":[{"name":"Mei","stars":5,"text":"Café coffee jelly!"},{"name":"Dan","stars":4,"text":"Coffee you can eat."},{"name":"Riya","stars":3,"text":"Ask if made with agar."}]},"photo":{"src":"images/coffee-jelly.jpg","title":"Coffee jelly (2014-01-23).jpg","author":"Lombroso","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"https://commons.wikimedia.org/wiki/File:Coffee_jelly_(2014-01-23).jpg","thumb":"images/thumb/coffee-jelly.jpg"}},"chahan":{"pron":"CHAH-hahn","what":"Japanese-style fried rice: rice stir-fried fast with egg, spring onion and usually pork, ham or chashu, seasoned lightly with soy. Often served with ramen or gyoza.","ingredients":["Cooked rice","Egg","Spring onion","Chashu pork or ham","Soy sauce & pepper"],"texture":["Fluffy","Slightly crisp"],"goodFor":["Fried rice fans","Mild eaters","Ramen shops"],"tip":"\"Han-chahan\" is a half portion, made to go with ramen.","steps":[{"icon":"🥄","text":"Eat with the flat-bottomed spoon it comes with."},{"icon":"🍜","text":"Alternate bites with ramen soup if you ordered a set."},{"icon":"🥟","text":"Pair with gyoza for a classic ramen-shop meal."}],"reviews":{"rating":4.5,"summary":"Simple, savoury comfort. Lighter than Chinese fried rice.","loved":["Fluffy egg","Savoury"],"watch":["Usually has pork","Can be oily"],"samples":[{"name":"Kenji","stars":5,"text":"Ramen + chahan half set is the best deal."},{"name":"Priya","stars":4,"text":"Like egg fried rice but lighter."},{"name":"Tom","stars":4,"text":"Ask for no pork if needed."}]},"photo":{"src":"images/chahan.jpg","title":"Ramen and Chahan 002.jpg","author":"Ocdp","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"https://commons.wikimedia.org/wiki/File:Ramen_and_Chahan_002.jpg","thumb":"images/thumb/chahan.jpg"}},"donburi":{"pron":"DOHN-boo-ree","what":"Any big bowl of rice with a topping simmered or fried on top, like katsu, beef, chicken and egg, or tempura. The name of the topping comes first: gyudon, katsudon, oyakodon.","ingredients":["Steamed rice","Topping (beef, katsu, chicken & egg, tempura, or tofu)","Sweet soy-dashi sauce","Spring onion"],"texture":["Saucy rice","Varies by topping"],"goodFor":["Rice bowls","Quick meals","Mild eaters"],"tip":"Words ending in \"-don\" on a menu mean a donburi rice bowl.","steps":[{"icon":"🥢","text":"Eat from the bowl, lifting it close with chopsticks."},{"icon":"🍚","text":"Mix a little sauce-soaked rice with each bite of topping."},{"icon":"🌶️","text":"Add shichimi pepper or pickled ginger if offered."}],"reviews":{"rating":4.5,"summary":"Quick, filling, everywhere in Japan.","loved":["Filling","Cheap"],"watch":["Most are meat-based","Big portions"],"samples":[{"name":"Aiko","stars":5,"text":"The sauce soaking into rice is the best part."},{"name":"Dan","stars":4,"text":"Fast food done right."},{"name":"Meera","stars":4,"text":"Look for tofu or veggie-don."}]},"photo":{"src":"images/donburi.jpg","title":"Rice bowl topped with minced chicken, egg and eggplant (7472290460).jpg","author":"pelican from Tokyo, Japan","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"https://commons.wikimedia.org/wiki/File:Rice_bowl_topped_with_minced_chicken,_egg_and_eggplant_(7472290460).jpg","thumb":"images/thumb/donburi.jpg"}},"chazuke":{"pron":"oh-CHAH-zoo-keh","what":"Rice with hot green tea or dashi broth poured over it, topped with salmon, pickled plum, seaweed or wasabi. A light, soothing end to a meal or late-night snack.","ingredients":["Rice","Green tea or dashi","Salmon flakes or umeboshi","Nori & sesame","Wasabi"],"texture":["Soupy","Soft"],"goodFor":["Light eaters","Comfort food","Late night"],"tip":"Ume (pickled plum) chazuke is the vegetarian option, but check if broth is dashi (fish).","steps":[{"icon":"🍵","text":"Let the tea soak into the rice for a moment."},{"icon":"🥢","text":"Stir in the toppings."},{"icon":"🥣","text":"Lift the bowl and slurp, pushing rice in with chopsticks."}],"reviews":{"rating":4.3,"summary":"Gentle and comforting. Simple flavours.","loved":["Light","Soothing"],"watch":["Very mild","Plum topping is sour"],"samples":[{"name":"Yuki","stars":5,"text":"Perfect after drinking."},{"name":"Sam","stars":4,"text":"Rice soup with tea — surprisingly nice."},{"name":"Ana","stars":4,"text":"Try the salmon one first."}]},"photo":{"src":"images/chazuke.jpg","title":"Sake chazuke by matsukawa1971.jpg","author":"matsukawa1971","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"https://commons.wikimedia.org/wiki/File:Sake_chazuke_by_matsukawa1971.jpg","thumb":"images/thumb/chazuke.jpg"}},"champon":{"pron":"CHAHM-pon","what":"A Nagasaki noodle soup with thick noodles in a milky pork-chicken broth, loaded with stir-fried seafood, pork and lots of cabbage and vegetables.","ingredients":["Thick champon noodles","Pork & chicken broth","Shrimp, squid","Pork slices","Cabbage, bean sprouts, carrot"],"texture":["Chewy noodles","Crunchy veg"],"goodFor":["Noodle soups","Seafood","Veg lovers"],"tip":"Not the same as Korean jjamppong, which is red and spicy.","steps":[{"icon":"🥢","text":"Mix the toppings into the noodles first."},{"icon":"🥣","text":"Sip the creamy broth from the spoon."},{"icon":"🍜","text":"Slurp noodles — it's polite in Japan."}],"reviews":{"rating":4.4,"summary":"Hearty bowl with tons of veg.","loved":["Lots of veg","Creamy broth"],"watch":["Seafood & pork","Big bowl"],"samples":[{"name":"Haruto","stars":5,"text":"Nagasaki's soul food."},{"name":"Lily","stars":4,"text":"Like ramen with a stir-fry on top."},{"name":"Omar","stars":4,"text":"Not spicy at all."}]},"photo":{"src":"images/champon.jpg","title":"Shikairo Nagasaki Japan05s.jpg","author":"663highland","license":"CC BY 2.5","licenseUrl":"https://creativecommons.org/licenses/by/2.5","source":"https://commons.wikimedia.org/wiki/File:Shikairo_Nagasaki_Japan05s.jpg","thumb":"images/thumb/champon.jpg"}},"agedashi-tofu":{"pron":"AH-geh-DAH-shee TOH-foo","what":"Cubes of silky tofu dusted in starch, fried until lightly crisp, then served in a warm dashi-soy broth with grated radish, ginger and spring onion.","ingredients":["Silken tofu","Potato starch","Dashi broth","Soy & mirin","Grated daikon, ginger"],"texture":["Crisp outside","Silky inside"],"goodFor":["Tofu lovers","Mild flavours","Izakaya snacks"],"tip":"The tofu is vegetarian but dashi is fish stock — ask for kombu dashi.","steps":[{"icon":"🥢","text":"Pick up a cube gently — it's soft."},{"icon":"🥣","text":"Dip it in the broth so the coating soaks it up."},{"icon":"🥄","text":"Drink the leftover broth with a spoon."}],"reviews":{"rating":4.5,"summary":"Delicate, warming izakaya favourite.","loved":["Silky tofu","Light broth"],"watch":["Broth usually has fish (dashi)"],"samples":[{"name":"Mei","stars":5,"text":"Crispy-soft contrast is perfect."},{"name":"Raj","stars":4,"text":"Great for tofu beginners."},{"name":"Chloe","stars":4,"text":"Order fast before it gets soggy."}]},"photo":{"src":"images/agedashi-tofu.jpg","title":"Agedashi tofu, fried tofu with broth.jpg","author":"HungryHuy","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"https://commons.wikimedia.org/wiki/File:Agedashi_tofu,_fried_tofu_with_broth.jpg","thumb":"images/thumb/agedashi-tofu.jpg"}},"hiyayakko":{"pron":"hee-yah-YAHK-koh","what":"A chilled block of silken tofu topped with grated ginger, spring onion, bonito flakes and a drizzle of soy. A cool summer side dish.","ingredients":["Chilled silken tofu","Soy sauce","Grated ginger","Spring onion","Bonito flakes"],"texture":["Silky","Cold"],"goodFor":["Light eaters","Summer","Tofu lovers"],"tip":"Ask \"katsuobushi nashi\" (no bonito flakes) to keep it vegetarian.","steps":[{"icon":"🥢","text":"Break off a piece with chopsticks."},{"icon":"🧂","text":"Make sure each bite has soy and topping."},{"icon":"🧊","text":"Eat it while still cold."}],"reviews":{"rating":4.2,"summary":"Refreshing but very plain for some.","loved":["Refreshing","Light"],"watch":["Bland if you dislike tofu","Bonito is fish"],"samples":[{"name":"Sora","stars":5,"text":"Perfect on a hot day."},{"name":"Mike","stars":3,"text":"Just cold tofu — fine."},{"name":"Neha","stars":4,"text":"Ask without bonito for veg."}]},"photo":{"src":"images/hiyayakko.jpg","title":"Hiyayakko with bonito flakes and welsh onion 2.jpg","author":"Dllu","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"https://commons.wikimedia.org/wiki/File:Hiyayakko_with_bonito_flakes_and_welsh_onion_2.jpg","thumb":"images/thumb/hiyayakko.jpg"}},"makizushi":{"pron":"MAH-kee-ZOO-shee","what":"Sushi rice and fillings rolled inside a sheet of nori seaweed and cut into rounds. Ranges from thin cucumber or tuna rolls (hosomaki) to fat rolls (futomaki).","ingredients":["Vinegared rice","Nori seaweed","Raw fish, cucumber or egg","Soy sauce","Wasabi & pickled ginger"],"texture":["Sticky rice","Crisp seaweed"],"goodFor":["Sushi beginners","Seafood","Light meals"],"tip":"Kappa maki (cucumber) and oshinko (pickle) rolls are vegetarian.","steps":[{"icon":"🥢","text":"Pick up a piece with chopsticks or fingers."},{"icon":"🐟","text":"Dip the fish side lightly in soy, not the rice."},{"icon":"🫚","text":"Eat ginger between pieces to refresh your mouth."}],"reviews":{"rating":4.6,"summary":"The easiest sushi to start with.","loved":["Bite-size","Many veg options"],"watch":["Raw fish in many","Wasabi heat"],"samples":[{"name":"Ren","stars":5,"text":"Kappa maki is my go-to."},{"name":"Sara","stars":4,"text":"Good for sushi beginners."},{"name":"Arjun","stars":4,"text":"Avocado & cucumber rolls are veg."}]},"photo":{"src":"images/makizushi.jpg","title":"Homemade sushi rolls, 2009.jpg","author":"Stacy","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"https://commons.wikimedia.org/wiki/File:Homemade_sushi_rolls,_2009.jpg","thumb":"images/thumb/makizushi.jpg"}},"nikujaga":{"pron":"nee-koo-JAH-gah","what":"Japanese home-style stew of thin beef or pork slices simmered with potatoes, onion and carrots in sweet soy and dashi. Japan's \"mum's cooking\" classic.","ingredients":["Thin beef or pork","Potatoes","Onion, carrot","Soy, mirin, sugar","Dashi"],"texture":["Soft potatoes","Tender meat"],"goodFor":["Comfort food","Mild eaters","Home cooking"],"tip":"Often part of a set meal (teishoku) with rice, soup and pickles.","steps":[{"icon":"🍚","text":"Eat with a bowl of rice."},{"icon":"🥢","text":"Break potatoes with chopsticks."},{"icon":"🥣","text":"Spoon the sweet broth over rice."}],"reviews":{"rating":4.5,"summary":"Warm, sweet-savoury comfort food.","loved":["Homely","Mild"],"watch":["Sweet for some","Meat-based"],"samples":[{"name":"Takumi","stars":5,"text":"Tastes like home."},{"name":"Grace","stars":4,"text":"A sweet Japanese meat and potatoes."},{"name":"Vik","stars":4,"text":"Lovely with miso soup."}]},"photo":{"src":"images/nikujaga.jpg","title":"Braised pork and potatoes (3089327692).jpg","author":"Yumi Kimura from Yokohama, JAPAN","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"https://commons.wikimedia.org/wiki/File:Braised_pork_and_potatoes_(3089327692).jpg","thumb":"images/thumb/nikujaga.jpg"}},"hayashi-rice":{"pron":"hah-YAH-shee","what":"Thin beef and onions in a rich brown demi-glace sauce with tomato and red wine, served over rice. Like Japanese curry but sweet and tangy instead of spicy.","ingredients":["Thin beef","Onion & mushrooms","Demi-glace sauce","Tomato & red wine","Rice"],"texture":["Saucy","Tender beef"],"goodFor":["Mild eaters","Beef lovers","Kids"],"tip":"Often on menus next to curry rice and omurice at yoshoku cafés.","steps":[{"icon":"🥄","text":"Eat with a spoon like curry rice."},{"icon":"🍚","text":"Mix sauce and rice as you go."},{"icon":"🥗","text":"Pair with a small salad."}],"reviews":{"rating":4.3,"summary":"Rich, sweet-tangy; kids love it.","loved":["Not spicy","Rich sauce"],"watch":["Sweet","Beef-based"],"samples":[{"name":"Mika","stars":5,"text":"Childhood favourite."},{"name":"Ben","stars":4,"text":"Beef stroganoff meets curry rice."},{"name":"Lina","stars":4,"text":"Good if curry's too spicy."}]},"photo":{"src":"images/hayashi-rice.jpg","title":"Hayashi rice.jpg","author":"Hiratake at Japanese Wikipedia","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/","source":"https://commons.wikimedia.org/wiki/File:Hayashi_rice.jpg","thumb":"images/thumb/hayashi-rice.jpg"}},"kakigori":{"pron":"kah-kee-GOH-ree","what":"A big mound of fluffy shaved ice soaked in flavoured syrup — strawberry, matcha, mango — often topped with condensed milk, sweet beans or fruit.","ingredients":["Finely shaved ice","Flavoured syrup","Condensed milk","Sweet red beans or fruit"],"texture":["Fluffy","Melts fast"],"goodFor":["Sweet tooth","Hot days","Light desserts"],"tip":"The flag with 氷 (ice) outside a shop means kakigōri is sold.","steps":[{"icon":"🥄","text":"Start from the top and dig down slowly."},{"icon":"🍯","text":"Pour extra syrup if given on the side."},{"icon":"⏱️","text":"Eat fast before it collapses."}],"reviews":{"rating":4.5,"summary":"Summer must; light and fun.","loved":["Refreshing","Huge portion"],"watch":["Mostly sugar","Brain freeze"],"samples":[{"name":"Hina","stars":5,"text":"Matcha with condensed milk — perfect."},{"name":"Joe","stars":4,"text":"Way fluffier than a snow cone."},{"name":"Asha","stars":4,"text":"Share one — it's big."}]},"photo":{"src":"images/kakigori.jpg","title":"Macha kakigori snow cone.jpg","author":"Unknown","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"https://commons.wikimedia.org/wiki/File:Macha_kakigori_snow_cone.jpg","thumb":"images/thumb/kakigori.jpg"}},"anmitsu":{"pron":"AHN-mee-tsoo","what":"A traditional dessert bowl of clear agar jelly cubes, sweet red bean paste, fruit and chewy mochi balls, with dark brown sugar syrup poured over.","ingredients":["Agar jelly cubes","Sweet red bean paste","Fruit","Shiratama mochi","Kuromitsu (black sugar syrup)"],"texture":["Jelly","Chewy","Juicy"],"goodFor":["Light desserts","Textures","Japanese sweets"],"tip":"\"Cream anmitsu\" adds a scoop of ice cream on top.","steps":[{"icon":"🍯","text":"Pour the black syrup over everything."},{"icon":"🥄","text":"Get jelly, bean and fruit in each spoonful."},{"icon":"🍡","text":"Save a mochi ball for the end."}],"reviews":{"rating":4.3,"summary":"Light and fun mix of textures.","loved":["Textures","Not too heavy"],"watch":["Agar jelly is plain on its own"],"samples":[{"name":"Aya","stars":5,"text":"Tea-house classic."},{"name":"Paul","stars":4,"text":"Interesting mix of jellies."},{"name":"Riya","stars":4,"text":"Add ice cream for cream anmitsu."}]},"photo":{"src":"images/anmitsu.jpg","title":"Anmitsu 001.jpg","author":"Ocdp","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"https://commons.wikimedia.org/wiki/File:Anmitsu_001.jpg","thumb":"images/thumb/anmitsu.jpg"}},"imagawayaki":{"pron":"ee-mah-GAH-wah-yah-kee","what":"Thick round cakes cooked in a special pan and filled with sweet red bean paste, custard or other fillings. Sold hot from street stalls and festivals.","ingredients":["Batter (flour, egg, milk)","Red bean paste","Custard (optional)"],"texture":["Soft","Gooey filling"],"goodFor":["Street sweets","Sweet tooth","Kids"],"tip":"Also called obanyaki or kaitenyaki depending on the region.","steps":[{"icon":"✋","text":"Hold it in a paper wrap — it's hot."},{"icon":"😋","text":"Bite from the edge."},{"icon":"🔁","text":"Try one red bean and one custard."}],"reviews":{"rating":4.5,"summary":"Warm, cheap and filling.","loved":["Hot & fresh","Sweet filling"],"watch":["Very hot filling"],"samples":[{"name":"Kaito","stars":5,"text":"Festival favourite."},{"name":"Emma","stars":4,"text":"Like a stuffed pancake puck."},{"name":"Dev","stars":4,"text":"Custard ones are amazing."}]},"photo":{"src":"images/imagawayaki.jpg","title":"Imagawayaki 001.jpg","author":"Ocdp","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"https://commons.wikimedia.org/wiki/File:Imagawayaki_001.jpg","thumb":"images/thumb/imagawayaki.jpg"}},"takikomi-gohan":{"pron":"tah-kee-KOH-mee GOH-hahn","what":"Rice cooked together with dashi, soy, mushrooms, carrot, burdock and sometimes chicken, so every grain is seasoned. A gentle, savoury mixed rice.","ingredients":["Rice","Dashi & soy","Shiitake mushrooms","Carrot, burdock","Chicken (optional)"],"texture":["Soft","Slightly sticky"],"goodFor":["Rice lovers","Mild eaters","Set meals"],"tip":"Look for \"kinoko\" (mushroom) versions in autumn.","steps":[{"icon":"🍚","text":"Eat it from a small rice bowl."},{"icon":"🥢","text":"Pair with miso soup and pickles."},{"icon":"🍙","text":"Leftovers are made into onigiri."}],"reviews":{"rating":4.4,"summary":"Comforting and aromatic.","loved":["Flavourful rice","Mild"],"watch":["Dashi has fish"],"samples":[{"name":"Natsu","stars":5,"text":"Autumn mushroom version is the best."},{"name":"Leo","stars":4,"text":"Seasoned rice — simple, tasty."},{"name":"Shreya","stars":4,"text":"Ask for kombu dashi if veg."}]},"photo":{"src":"images/takikomi-gohan.jpg","title":"Kashiwa gohan.JPG","author":"Nissy-KITAQ","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"https://commons.wikimedia.org/wiki/File:Kashiwa_gohan.JPG","thumb":"images/thumb/takikomi-gohan.jpg"}},"tamago-kake-gohan":{"pron":"tah-MAH-goh kah-keh GOH-hahn","what":"Hot rice mixed with a raw egg and a splash of soy sauce, stirred until creamy. A simple Japanese breakfast, safe there because eggs are produced to be eaten raw.","ingredients":["Hot rice","Raw egg","Soy sauce","Spring onion or nori"],"texture":["Creamy","Silky"],"goodFor":["Adventurous eaters","Breakfast","Egg lovers"],"tip":"Often shortened to \"TKG\". Only eat raw egg where eggs are safe for it.","steps":[{"icon":"🥢","text":"Make a small well in the rice."},{"icon":"🥚","text":"Crack the egg in, add soy."},{"icon":"🌀","text":"Stir quickly until fluffy, then eat."}],"reviews":{"rating":4.2,"summary":"Love it or hate it — raw egg texture.","loved":["Creamy","Simple"],"watch":["Raw egg"],"samples":[{"name":"Kenta","stars":5,"text":"Breakfast of champions."},{"name":"Holly","stars":3,"text":"Couldn't get past raw egg."},{"name":"Yash","stars":4,"text":"Surprisingly creamy."}]},"photo":{"src":"images/tamago-kake-gohan.jpg","title":"Tamagokake-gohan.JPG","author":"Unknown","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/","source":"https://commons.wikimedia.org/wiki/File:Tamagokake-gohan.JPG","thumb":"images/thumb/tamago-kake-gohan.jpg"}},"tendon":{"pron":"TEN-don","what":"A rice bowl topped with crispy tempura — shrimp, fish and vegetables — drizzled with a sweet, thick soy sauce. Not to be confused with the body part!","ingredients":["Steamed rice","Shrimp tempura","Vegetable tempura","Sweet tare sauce"],"texture":["Crispy","Saucy rice"],"goodFor":["Fried food","Rice bowls","Mild eaters"],"tip":"Veg-only (yasai) tendon exists; the sauce may still use dashi.","steps":[{"icon":"🍤","text":"Eat the crispy tempura first while crunchy."},{"icon":"🍚","text":"Mix sauce-soaked rice with veg pieces."},{"icon":"🫚","text":"Pickles on the side reset your palate."}],"reviews":{"rating":4.5,"summary":"Crunchy, satisfying, filling.","loved":["Crispy tempura","Sweet sauce"],"watch":["Fried & heavy","Shrimp"],"samples":[{"name":"Riku","stars":5,"text":"Tenya chains do great tendon."},{"name":"Nora","stars":4,"text":"Tempura plus rice — what's not to love."},{"name":"Kabir","stars":4,"text":"Ask for veg-only tempura."}]},"photo":{"src":"images/tendon.jpg","title":"Tendon one meal.jpg","author":"LR0725","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"https://commons.wikimedia.org/wiki/File:Tendon_one_meal.jpg","thumb":"images/thumb/tendon.jpg"}},"unadon":{"pron":"OO-nah-don","what":"Grilled freshwater eel glazed with sweet soy sauce, laid over rice in a lacquer box or bowl. Rich, smoky and a special-occasion dish in Japan.","ingredients":["Grilled eel (unagi)","Sweet tare glaze","Steamed rice","Sansho pepper"],"texture":["Soft","Melt-in-mouth"],"goodFor":["Seafood","Special meals","Sweet-savoury"],"tip":"\"Unajū\" is the same dish served in a square box.","steps":[{"icon":"🌿","text":"Sprinkle a little sansho pepper over the eel."},{"icon":"🥢","text":"Eat eel and rice together."},{"icon":"🥣","text":"Comes with liver soup (kimosui) sometimes."}],"reviews":{"rating":4.6,"summary":"Rich, luxurious, pricey.","loved":["Smoky-sweet","Tender"],"watch":["Expensive","Small bones"],"samples":[{"name":"Hiro","stars":5,"text":"Summer stamina food."},{"name":"Kate","stars":4,"text":"Doesn't taste fishy at all."},{"name":"Ravi","stars":4,"text":"Worth the splurge once."}]},"photo":{"src":"images/unadon.jpg","title":"2008-06-07 close-up of unajyuu (heavy eel) on rice.jpg","author":"sodai gomi","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"https://commons.wikimedia.org/wiki/File:2008-06-07_close-up_of_unajyuu_(heavy_eel)_on_rice.jpg","thumb":"images/thumb/unadon.jpg"}},"nigirizushi":{"pron":"nee-GEE-ree","what":"Hand-pressed blocks of vinegared rice topped with a slice of fish or seafood, often with a dab of wasabi between. The classic sushi-counter style.","ingredients":["Vinegared rice","Raw fish (tuna, salmon) or seafood","Wasabi","Soy sauce","Pickled ginger"],"texture":["Soft fish","Loose rice"],"goodFor":["Seafood lovers","Adventurous eaters","Sushi fans"],"tip":"Tamago (sweet egg) and inari are good non-raw options.","steps":[{"icon":"✋","text":"Pick it up with fingers or chopsticks."},{"icon":"🔄","text":"Turn it over and dip the fish side in soy."},{"icon":"😋","text":"Eat in one bite."}],"reviews":{"rating":4.7,"summary":"The purest sushi experience.","loved":["Fresh fish","One bite"],"watch":["Raw fish","Pricey"],"samples":[{"name":"Sho","stars":5,"text":"Salmon nigiri melts."},{"name":"Jen","stars":4,"text":"Fish side down in soy — game changer."},{"name":"Anil","stars":3,"text":"Try tamago (egg) nigiri first."}]},"photo":{"src":"images/nigirizushi.jpg","title":"Nigiri Sushi (25966163204).jpg","author":"Tim Reckmann from Hamm, Deutschland","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"https://commons.wikimedia.org/wiki/File:Nigiri_Sushi_(25966163204).jpg","thumb":"images/thumb/nigirizushi.jpg"}},"chirashizushi":{"pron":"chee-RAH-shee","what":"A bowl of sushi rice \"scattered\" with sliced raw fish, egg, roe and vegetables. Like a deconstructed sushi platter.","ingredients":["Vinegared rice","Assorted sashimi","Egg strips","Fish roe","Cucumber, nori"],"texture":["Mixed","Soft fish"],"goodFor":["Seafood lovers","Sushi fans","Variety"],"tip":"Kansai-style chirashi uses cooked toppings mixed into the rice.","steps":[{"icon":"🥢","text":"Pick a piece of fish with a bit of rice."},{"icon":"🧂","text":"Drizzle soy on top rather than dipping."},{"icon":"🌿","text":"Mix a little wasabi into the soy first."}],"reviews":{"rating":4.5,"summary":"Colourful and good value.","loved":["Variety","Pretty bowl"],"watch":["Raw fish"],"samples":[{"name":"Mio","stars":5,"text":"Best way to try many fish at once."},{"name":"Chris","stars":4,"text":"Great lunch deal."},{"name":"Tara","stars":4,"text":"Pour soy carefully."}]},"photo":{"src":"images/chirashizushi.jpg","title":"Chirashi-zushi.jpg","author":"Arashiyama","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"https://commons.wikimedia.org/wiki/File:Chirashi-zushi.jpg","thumb":"images/thumb/chirashizushi.jpg"}},"curry-bread":{"pron":"KAH-reh pahn","what":"A bread bun stuffed with thick Japanese curry, coated in breadcrumbs and deep-fried until crunchy. A bakery and convenience-store favourite.","ingredients":["Bread dough","Japanese curry filling","Panko breadcrumbs","Oil for frying"],"texture":["Crunchy","Soft","Saucy"],"goodFor":["Snacks","Curry lovers","Bakeries"],"tip":"Some bakeries sell baked (not fried) curry bread too.","steps":[{"icon":"✋","text":"Hold with the paper wrap."},{"icon":"😋","text":"Bite at an angle to reach the filling."},{"icon":"🔥","text":"Best eaten warm."}],"reviews":{"rating":4.6,"summary":"Crunchy, savoury, addictive.","loved":["Crispy shell","Curry inside"],"watch":["Oily","Usually has meat"],"samples":[{"name":"Yuto","stars":5,"text":"Fresh from the bakery — heaven."},{"name":"Megan","stars":4,"text":"Like a curry doughnut."},{"name":"Sid","stars":4,"text":"Ask if a veg one is available."}]},"photo":{"src":"images/curry-bread.jpg","title":"Deep fried curry bread.jpg","author":"Laitr Keiows","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"https://commons.wikimedia.org/wiki/File:Deep_fried_curry_bread.jpg","thumb":"images/thumb/curry-bread.jpg"}},"katsu-sando":{"pron":"KAHT-soo SAHN-doh","what":"A crumbed pork cutlet with tonkatsu sauce and cabbage between fluffy white milk bread, crusts cut off, sliced into neat rectangles.","ingredients":["Pork cutlet (tonkatsu)","Shokupan milk bread","Tonkatsu sauce","Shredded cabbage","Mustard"],"texture":["Crunchy","Soft bread"],"goodFor":["Sandwiches","Fried food","Quick lunch"],"tip":"\"Hire katsu sando\" uses tenderloin and is extra tender.","steps":[{"icon":"✋","text":"Eat with hands."},{"icon":"😋","text":"Hold the pieces together — the cutlet is thick."},{"icon":"🔁","text":"Wagyu versions cost much more."}],"reviews":{"rating":4.5,"summary":"Simple, perfect sandwich.","loved":["Crispy pork","Soft bread"],"watch":["Pork","Heavy"],"samples":[{"name":"Daiki","stars":5,"text":"Train-station classic."},{"name":"Amy","stars":4,"text":"Simple but so good."},{"name":"Rohan","stars":4,"text":"Chicken katsu sando also exists."}]},"photo":{"src":"images/katsu-sando.jpg","title":"KatsuSando6515.jpg","author":"No machine-readable author provided. Fg2 assumed (based on copyright claims).","license":"Public domain","licenseUrl":"","source":"https://commons.wikimedia.org/wiki/File:KatsuSando6515.jpg","thumb":"images/thumb/katsu-sando.jpg"}},"kushikatsu":{"pron":"KOO-shee-KAHT-soo","what":"Skewers of meat, seafood and vegetables coated in breadcrumbs and deep-fried. Osaka-style, you dip them in a shared pot of thin sauce.","ingredients":["Pork, chicken, shrimp","Vegetables (onion, lotus, pumpkin)","Panko","Thin Worcester-style sauce","Raw cabbage"],"texture":["Crunchy"],"goodFor":["Fried snacks","Bar food","Groups"],"tip":"Free cabbage is for scooping sauce if you need more.","steps":[{"icon":"🥢","text":"Dip the skewer in the sauce pot ONCE — no double dipping!"},{"icon":"🥬","text":"Use cabbage to scoop more sauce."},{"icon":"🍢","text":"Put used sticks in the cup provided."}],"reviews":{"rating":4.5,"summary":"Fun, cheap Osaka bar food.","loved":["Crunchy","Variety"],"watch":["Oily","No double-dipping rule"],"samples":[{"name":"Kei","stars":5,"text":"Shinsekai must-do."},{"name":"Lucy","stars":4,"text":"The no-double-dip sign is serious."},{"name":"Ajay","stars":4,"text":"Veg skewers are great."}]},"photo":{"src":"images/kushikatsu.jpg","title":"串カツ（神谷バー・浅草） (3027765488).jpg","author":"kimishowota","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"https://commons.wikimedia.org/wiki/File:%E4%B8%B2%E3%82%AB%E3%83%84%EF%BC%88%E7%A5%9E%E8%B0%B7%E3%83%90%E3%83%BC%E3%83%BB%E6%B5%85%E8%8D%89%EF%BC%89_(3027765488).jpg","thumb":"images/thumb/kushikatsu.jpg"}},"ebi-furai":{"pron":"EH-bee FOO-rye","what":"Large shrimp coated in panko breadcrumbs and deep-fried, served with tartar sauce, cabbage and rice. A yoshoku (Western-style) classic.","ingredients":["Large shrimp","Panko breadcrumbs","Tartar sauce","Shredded cabbage","Lemon"],"texture":["Crunchy","Juicy"],"goodFor":["Seafood","Fried food","Mild eaters"],"tip":"Tempura is light batter; ebi fry is breadcrumbs.","steps":[{"icon":"🍋","text":"Squeeze lemon over."},{"icon":"🥄","text":"Dip in tartar sauce."},{"icon":"🍚","text":"Eat with rice and cabbage."}],"reviews":{"rating":4.5,"summary":"Crunchy, juicy, kid-friendly.","loved":["Big shrimp","Crunch"],"watch":["Fried","Shellfish"],"samples":[{"name":"Nao","stars":5,"text":"Bento box hero."},{"name":"Will","stars":4,"text":"Panko makes it super crisp."},{"name":"Sunita","stars":4,"text":"Different from tempura — thicker crust."}]},"photo":{"src":"images/ebi-furai.jpg","title":"CdazziEbifurai1.jpg","author":"小太刀","license":"CC BY-SA 3.0","licenseUrl":"http://creativecommons.org/licenses/by-sa/3.0/","source":"https://commons.wikimedia.org/wiki/File:CdazziEbifurai1.jpg","thumb":"images/thumb/ebi-furai.jpg"}},"kakiage":{"pron":"KAH-kee-AH-geh","what":"A crispy tempura fritter made of shredded vegetables (onion, carrot, burdock) and sometimes small shrimp, fried together in a loose cake. Served on soba, udon or rice.","ingredients":["Shredded onion & carrot","Burdock or greens","Small shrimp (optional)","Tempura batter"],"texture":["Crispy","Lacy"],"goodFor":["Fried snacks","Veg lovers","Noodle toppings"],"tip":"Pakora fans will love it — it's like a lacy onion bhaji.","steps":[{"icon":"🥢","text":"Break it into pieces."},{"icon":"🍜","text":"Let it soak a bit in noodle soup — or eat it crisp."},{"icon":"🧂","text":"Dip in tentsuyu sauce or salt."}],"reviews":{"rating":4.3,"summary":"Crunchy veg fritter; great on noodles.","loved":["Crunchy","Veg-packed"],"watch":["Oily"],"samples":[{"name":"Sota","stars":5,"text":"Kakiage soba is standing-noodle-bar classic."},{"name":"Jess","stars":4,"text":"Like a Japanese onion bhaji."},{"name":"Kiran","stars":4,"text":"Ask for no shrimp."}]},"photo":{"src":"images/kakiage.jpg","title":"Kakiage tendon by chidorian.jpg","author":"chidorian","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"https://commons.wikimedia.org/wiki/File:Kakiage_tendon_by_chidorian.jpg","thumb":"images/thumb/kakiage.jpg"}},"doenjang-jjigae":{"pron":"DWEN-jahng JJEE-geh","what":"Korea's everyday stew of fermented soybean paste with tofu, zucchini, potato, onion and chilli, often with clams or beef. Earthy, salty, bubbling hot.","ingredients":["Doenjang (soybean paste)","Tofu","Zucchini, potato, onion","Green chilli","Clams or beef (optional)"],"texture":["Brothy","Soft tofu"],"goodFor":["Stews","Savoury","Adventurous eaters"],"tip":"Often comes free with Korean BBQ.","steps":[{"icon":"🍚","text":"Eat with rice."},{"icon":"🥄","text":"Spoon stew over rice or eat between bites."},{"icon":"🔥","text":"It's served boiling — blow first."}],"reviews":{"rating":4.5,"summary":"Deep, savoury, homey.","loved":["Earthy flavour","Warming"],"watch":["Strong fermented smell","Very salty"],"samples":[{"name":"Jiwoo","stars":5,"text":"Korean comfort in a pot."},{"name":"Mark","stars":4,"text":"Like miso soup's punchier cousin."},{"name":"Pooja","stars":4,"text":"Ask for no seafood."}]},"photo":{"src":"images/doenjang-jjigae.jpg","title":"Doenjang-jjigae.jpg","author":"jyleen21","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"https://commons.wikimedia.org/wiki/File:Doenjang-jjigae.jpg","thumb":"images/thumb/doenjang-jjigae.jpg"}},"galbi-jjim":{"pron":"GAHL-bee JJIM","what":"Beef short ribs slowly braised in sweet soy, garlic and pear with carrots, radish, chestnuts and jujubes until falling off the bone. A festive Korean dish.","ingredients":["Beef short ribs","Soy sauce & sugar","Asian pear, garlic","Radish, carrot","Chestnuts, jujubes"],"texture":["Fall-apart tender","Sticky"],"goodFor":["Beef lovers","Sweet-savoury","Celebrations"],"tip":"\"Maeun galbi-jjim\" is the spicy version.","steps":[{"icon":"🥢","text":"Pull meat off the bone with chopsticks."},{"icon":"🍚","text":"Spoon sauce over rice."},{"icon":"🥬","text":"Eat with kimchi to cut the richness."}],"reviews":{"rating":4.7,"summary":"Sweet, rich, tender — crowd pleaser.","loved":["Tender meat","Sweet sauce"],"watch":["Pricey","Beef"],"samples":[{"name":"Minho","stars":5,"text":"Holiday table star."},{"name":"Sarah","stars":4,"text":"Like a Korean pot roast."},{"name":"Ankit","stars":4,"text":"Spicy versions exist too."}]},"photo":{"src":"images/galbi-jjim.jpg","title":"Korean braised beef short ribs-Galbijjim.jpg","author":"by Junho Jung at Flickr from South Korea","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","source":"https://commons.wikimedia.org/wiki/File:Korean_braised_beef_short_ribs-Galbijjim.jpg","thumb":"images/thumb/galbi-jjim.jpg"}},"gyeran-jjim":{"pron":"GYEH-rahn JJIM","what":"Eggs beaten with broth and steamed in a hot stone pot until puffed and fluffy like a soufflé. A free or cheap side at Korean BBQ restaurants.","ingredients":["Eggs","Water or anchovy broth","Spring onion","Salt or salted shrimp"],"texture":["Fluffy","Custardy"],"goodFor":["Egg lovers","Mild eaters","BBQ side"],"tip":"Ask for a \"volcano\" gyeran-jjim — it puffs over the pot.","steps":[{"icon":"🥄","text":"Scoop with a spoon."},{"icon":"🔥","text":"It's very hot — blow on it."},{"icon":"🍖","text":"Eat between spicy BBQ bites to cool down."}],"reviews":{"rating":4.6,"summary":"Soft, comforting, great with spicy food.","loved":["Fluffy","Mild"],"watch":["Very hot","Broth may have anchovy"],"samples":[{"name":"Yuna","stars":5,"text":"Volcano egg is so satisfying."},{"name":"Josh","stars":4,"text":"Perfect palate cleanser."},{"name":"Leela","stars":4,"text":"Kid-friendly."}]},"photo":{"src":"images/gyeran-jjim.jpg","title":"1005 eggjjim.jpg","author":"Nuyos at en.wikipedia","license":"Public domain","licenseUrl":"","source":"https://commons.wikimedia.org/wiki/File:1005_eggjjim.jpg","thumb":"images/thumb/gyeran-jjim.jpg"}},"bindae-tteok":{"pron":"BIN-deh TTEOK","what":"A thick, crispy pancake made from ground mung beans with kimchi, bean sprouts and often pork, fried in plenty of oil. Famous at Seoul's Gwangjang Market.","ingredients":["Ground mung beans","Kimchi","Bean sprouts","Pork (optional)","Soy-onion dipping sauce"],"texture":["Crispy edges","Soft inside"],"goodFor":["Savoury snacks","Pancake lovers","Markets"],"tip":"Different from pajeon, which uses flour batter and spring onions.","steps":[{"icon":"✂️","text":"Tear or cut into pieces."},{"icon":"🧅","text":"Dip in soy sauce with onions."},{"icon":"🍶","text":"Pairs with makgeolli (rice wine)."}],"reviews":{"rating":4.5,"summary":"Crispy, nutty, filling.","loved":["Crispy","Nutty"],"watch":["Oily","May have pork"],"samples":[{"name":"Hyun","stars":5,"text":"Gwangjang Market essential."},{"name":"Kim","stars":4,"text":"Thicker than pajeon."},{"name":"Arnav","stars":4,"text":"Veg versions available."}]},"photo":{"src":"images/bindae-tteok.jpg","title":"Korea GwangjangMarket Eats 11 Bindaetteok.jpg","author":"Korea.net / Korean Culture and Information Service","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","source":"https://commons.wikimedia.org/wiki/File:Korea_GwangjangMarket_Eats_11_Bindaetteok.jpg","thumb":"images/thumb/bindae-tteok.jpg"}},"kong-guksu":{"pron":"KONG GOOK-soo","what":"Wheat noodles in an ice-cold, thick soy milk broth made from ground soybeans, topped with cucumber and sesame. A summer dish in Korea.","ingredients":["Wheat noodles","Ground soybean broth","Cucumber","Sesame seeds","Salt or sugar to taste"],"texture":["Creamy","Cold","Chewy"],"goodFor":["Vegetarians","Summer","Mild eaters"],"tip":"Salt it! The broth is unseasoned on purpose.","steps":[{"icon":"🧂","text":"Add salt (or sugar, regionally) to taste."},{"icon":"🥢","text":"Mix noodles in the thick broth."},{"icon":"🥣","text":"Drink the broth from the bowl."}],"reviews":{"rating":4.2,"summary":"Refreshing, nutty, very plain.","loved":["Refreshing","Vegetarian"],"watch":["Bland unless salted"],"samples":[{"name":"Seo","stars":5,"text":"Summer comfort."},{"name":"Dan","stars":3,"text":"Needs salt."},{"name":"Ritu","stars":4,"text":"Unique — creamy cold noodles."}]},"photo":{"src":"images/kong-guksu.jpg","title":"Korean noodles-Kongguksu-01.jpg","author":"egg (Hong, Yun Seon)","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"https://commons.wikimedia.org/wiki/File:Korean_noodles-Kongguksu-01.jpg","thumb":"images/thumb/kong-guksu.jpg"}},"bokkeum-bap":{"pron":"BOH-kkeum-BAHP","what":"Rice stir-fried with chopped kimchi, gochujang and often pork or spam, topped with a fried egg. Tangy, spicy and a great way to use old kimchi.","ingredients":["Rice","Kimchi","Gochujang","Pork, spam or tuna","Fried egg, sesame"],"texture":["Chewy","Crispy bits"],"goodFor":["Fried rice","Spicy food","Quick meals"],"tip":"At Korean BBQ, they'll fry leftover rice in the grill pan at the end — say yes.","steps":[{"icon":"🍳","text":"Break the egg yolk over the rice."},{"icon":"🥄","text":"Mix and scoop with a spoon."},{"icon":"🍲","text":"Scrape the crispy bottom if cooked in a pan."}],"reviews":{"rating":4.6,"summary":"Spicy, tangy, comforting.","loved":["Kimchi tang","Runny egg"],"watch":["Spicy","Often meat"],"samples":[{"name":"Bora","stars":5,"text":"Late night staple."},{"name":"Ryan","stars":4,"text":"Fried rice with a kick."},{"name":"Isha","stars":4,"text":"Ask without meat."}]},"photo":{"src":"images/bokkeum-bap.jpg","title":"Kimchi-bokkeum-bap (Kimchi fried rice) - Kogi 2023-09-11.jpg","author":"Andy Li","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","source":"https://commons.wikimedia.org/wiki/File:Kimchi-bokkeum-bap_(Kimchi_fried_rice)_-_Kogi_2023-09-11.jpg","thumb":"images/thumb/bokkeum-bap.jpg"}},"buldak-ramen":{"pron":"BOOL-dahk","what":"Very spicy instant stir-fried noodles with a fiery chicken-flavoured sauce. Famous from online \"fire noodle challenges\"; often served with cheese or egg.","ingredients":["Instant noodles","Hot chicken-flavour sauce","Seaweed & sesame flakes","Cheese or egg (optional)"],"texture":["Chewy","Saucy"],"goodFor":["Spice lovers","Challenges","Quick snacks"],"tip":"Carbonara and cheese flavours are a little milder than the original.","steps":[{"icon":"🥛","text":"Keep milk nearby."},{"icon":"🧀","text":"Add cheese or egg to tone down heat."},{"icon":"🥢","text":"Mix the sauce well before eating."}],"reviews":{"rating":4.1,"summary":"Fun if you love extreme heat.","loved":["Fiery","Addictive"],"watch":["Extremely spicy"],"samples":[{"name":"Joon","stars":5,"text":"Carbonara flavour is my favourite."},{"name":"Ella","stars":3,"text":"Too hot for me."},{"name":"Nikhil","stars":4,"text":"Add cheese — trust me."}]},"photo":{"src":"images/buldak-ramen.jpg","title":"Buldak Ramen 20210114 004.jpg","author":"Mobius6","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","source":"https://commons.wikimedia.org/wiki/File:Buldak_Ramen_20210114_004.jpg","thumb":"images/thumb/buldak-ramen.jpg"}},"gyeran-mari":{"pron":"GYEH-rahn MAH-ree","what":"A rolled omelette with chopped carrot, spring onion and sometimes ham, sliced into rounds. A common Korean side dish and lunchbox item.","ingredients":["Eggs","Carrot","Spring onion","Ham (optional)","Salt"],"texture":["Soft","Layered"],"goodFor":["Egg lovers","Mild eaters","Side dishes"],"tip":"Japanese tamagoyaki is sweeter; gyeran-mari is savoury.","steps":[{"icon":"🥢","text":"Pick up a slice."},{"icon":"🍅","text":"Dip in ketchup if you like."},{"icon":"🍚","text":"Eat with rice and other sides."}],"reviews":{"rating":4.5,"summary":"Simple, pretty, mild.","loved":["Soft","Colourful"],"watch":["Sometimes has ham"],"samples":[{"name":"Hana","stars":5,"text":"Lunchbox favourite."},{"name":"Liam","stars":4,"text":"Like tamagoyaki but savoury."},{"name":"Kavya","stars":4,"text":"Great for kids."}]},"photo":{"src":"images/gyeran-mari.jpg","title":"Gyeran-mari.jpg","author":"Hyeon-Jeong Suk","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","source":"https://commons.wikimedia.org/wiki/File:Gyeran-mari.jpg","thumb":"images/thumb/gyeran-mari.jpg"}}}]);
